def web_analytics_impl(inp):
    rows = inp["channels"]
    if len(rows) < 2:
        raise DataError("at least two channels are required")
    if len(rows) > 12:
        raise DataError("at most twelve channels are supported")
    parsed = []
    total_sessions = D(0); total_conversions = D(0); total_revenue = D(0)
    for i, row in enumerate(rows, 1):
        name = row["name"].strip()
        if not name or len(name) > 60:
            raise DataError("channel %d needs a name of at most 60 characters" % i)
        sessions = D(str(row["sessions"])); conversions = D(str(row["conversions"]))
        revenue = D(str(row["revenue"]))
        if sessions <= 0: raise DataError("channel %d sessions must be positive" % i)
        if conversions < 0 or conversions > sessions: raise DataError("channel %d conversions must lie between zero and its sessions" % i)
        if revenue < 0: raise DataError("channel %d revenue must be non-negative" % i)
        parsed.append((name, sessions, conversions, revenue))
        total_sessions += sessions; total_conversions += conversions; total_revenue += revenue
    out = {"total_sessions": total_sessions, "total_conversions": total_conversions,
           "total_revenue": total_revenue, "blended_conversion_rate": total_conversions / total_sessions,
           "revenue_per_session": total_revenue / total_sessions}
    for i, (name, sessions, conversions, revenue) in enumerate(parsed, 1):
        out["sessions_%d" % i] = sessions
        out["conversions_%d" % i] = conversions
        out["revenue_%d" % i] = revenue
        out["session_share_%d" % i] = sessions / total_sessions
        out["conversion_rate_%d" % i] = conversions / sessions
        out["revenue_per_session_%d" % i] = revenue / sessions
    organic_impressions = _optional_decimal(inp, "organic_impressions")
    organic_clicks = _optional_decimal(inp, "organic_clicks")
    if organic_impressions is not None or organic_clicks is not None:
        if organic_impressions is None or organic_clicks is None:
            raise DataError("declare both organic_impressions and organic_clicks, or neither")
        if organic_impressions <= 0: raise DataError("organic_impressions must be positive")
        if organic_clicks < 0 or organic_clicks > organic_impressions: raise DataError("organic_clicks must lie between zero and organic_impressions")
        out["organic_impressions"] = organic_impressions
        out["organic_clicks"] = organic_clicks
        out["organic_ctr"] = organic_clicks / organic_impressions
    return out

def _web_ref(inp):
    rows = inp["channels"]
    s = [float(D(str(r["sessions"]))) for r in rows]
    c = [float(D(str(r["conversions"]))) for r in rows]
    r = [float(D(str(r["revenue"]))) for r in rows]
    ts, tc, tr = sum(s), sum(c), sum(r)
    return {"total_sessions": ts, "total_conversions": tc, "total_revenue": tr,
            "blended_conversion_rate": tc / ts, "revenue_per_session": tr / ts,
            "session_share_1": s[0] / ts, "conversion_rate_1": c[0] / s[0], "revenue_per_session_1": r[0] / s[0]}

def web_analytics_tests(inp, impl):
    base, ref = impl(inp), _web_ref(inp)
    rows = inp["channels"]; n = len(rows)
    sessions = [D(str(r["sessions"])) for r in rows]
    conversions = [D(str(r["conversions"])) for r in rows]
    revenue = [D(str(r["revenue"])) for r in rows]
    ts, tc, tr = sum(sessions, D(0)), sum(conversions, D(0)), sum(revenue, D(0))
    checks = [
        ("second_implementation_agrees", all(_close(base[k], ref[k], rel=1e-9) for k in ref), "float route agrees with the Decimal route"),
        ("session_shares_sum_to_one", _close(sum((base["session_share_%d" % (i + 1)] for i in range(n)), D(0)), D(1)), "the channel session shares cover every session"),
        ("conversion_rate_is_conversions_over_sessions", all(_close(base["conversion_rate_%d" % (i + 1)], conversions[i] / sessions[i]) for i in range(n)), "each channel's conversion rate is its conversions over its sessions"),
        ("blended_conversion_rate_is_total_conversions_over_total_sessions", _close(base["blended_conversion_rate"], tc / ts), "the blended rate pools every channel"),
        ("revenue_per_session_is_revenue_over_sessions", all(_close(base["revenue_per_session_%d" % (i + 1)], revenue[i] / sessions[i]) for i in range(n)), "each channel's revenue per session uses its own revenue and sessions"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def web_analytics_profile(inp):
    try:
        rows = inp.get("channels")
        if not isinstance(rows, list) or len(rows) < 2: return ["at least two channels are required"]
        if len(rows) > 12: return ["at most twelve channels are supported"]
        for i, row in enumerate(rows, 1):
            if not isinstance(row, dict) or not isinstance(row.get("name"), str) or not row["name"].strip():
                return ["channel %d needs a name" % i]
            sessions = D(str(row.get("sessions"))); conversions = D(str(row.get("conversions")))
            revenue = D(str(row.get("revenue")))
            if sessions <= 0: return ["channel %d sessions must be positive" % i]
            if conversions < 0 or conversions > sessions: return ["channel %d conversions must lie between zero and its sessions" % i]
            if revenue < 0: return ["channel %d revenue must be non-negative" % i]
        oi = _optional_decimal(inp, "organic_impressions"); oc = _optional_decimal(inp, "organic_clicks")
        if (oi is None) != (oc is None): return ["declare both organic_impressions and organic_clicks, or neither"]
        if oi is not None:
            if oi <= 0: return ["organic_impressions must be positive"]
            if oc < 0 or oc > oi: return ["organic_clicks must lie between zero and organic_impressions"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["web inputs are malformed: each channel needs sessions, conversions and revenue"]

def _web_typing(metric):
    if metric.startswith(("session_share_", "conversion_rate_")) or metric in ("blended_conversion_rate", "organic_ctr"):
        return ("rate", 4)
    if metric.startswith(("revenue", "total_revenue")):
        return ("currency", 2)
    return ("count", 0)

def web_analytics_caveats(out, th):
    return ["Sessions, conversions and revenue are the numbers you declare; a session definition or attribution window that differs between channels makes the comparison unfair.",
            "Direct traffic and unattributed sessions are only visible if you declare them as a channel.",
            "No attribution, incrementality or bot filtering is applied; revenue is assigned to the channel that reported it."]

def web_analytics_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    t = ("The declared channels brought " + tok("total_sessions") + " sessions and " + tok("total_conversions") +
         " conversions, a blended conversion rate of " + tok("blended_conversion_rate") + " and " +
         tok("revenue_per_session") + " of revenue per session.")
    if "organic_ctr" in out:
        t += (" Organic search recorded " + tok("organic_ctr") + " click-through from " + tok("organic_impressions") + " impressions.")
    return t


# ---------- Segmentation and media planning (B-119) ----------

#: The eleven named segments of a five-by-five RFM grid, in the order the rules are
#: tried.  First match wins, so every customer falls in exactly one segment.
RFM_SEGMENTS = ("cannot_lose", "champions", "loyal", "potential_loyalist", "new",
                "promising", "need_attention", "at_risk", "about_to_sleep",
                "hibernating", "lost")

RFM_LABELS = {"cannot_lose": "Cannot lose them", "champions": "Champions", "loyal": "Loyal customers",
              "potential_loyalist": "Potential loyalists", "new": "New customers",
              "promising": "Promising", "need_attention": "Need attention", "at_risk": "At risk",
              "about_to_sleep": "About to sleep", "hibernating": "Hibernating", "lost": "Lost"}

def _rfm_segment(r, f, m):
    """The declared first-match rules of the five-by-five grid."""
    if r <= 2 and f >= 4 and m >= 4: return "cannot_lose"
    if r >= 4 and f >= 4 and m >= 4: return "champions"
    if r >= 3 and f >= 4: return "loyal"
    if r >= 4 and 2 <= f <= 3: return "potential_loyalist"
    if r >= 4 and f == 1: return "new"
    if r == 3 and f == 1: return "promising"
    if r == 3 and 2 <= f <= 3: return "need_attention"
    if r <= 2 and f >= 3: return "at_risk"
    if r == 2 and f <= 2: return "about_to_sleep"
    if r == 1 and f <= 2 and m <= 2: return "hibernating"
    return "lost"

def _rfm_positions(values, higher_is_better):
    """Competition rank per customer: one plus the number of strictly better values."""
    n = len(values)
    key = (lambda v: v) if higher_is_better else (lambda v: -v)
    order = sorted(range(n), key=lambda i: key(values[i]), reverse=True)
    pos = [0] * n
    last_key, last_pos = None, 0
    for place, i in enumerate(order, 1):
        k = key(values[i])
        if last_key is not None and k == last_key:
            pos[i] = last_pos
        else:
            pos[i] = place; last_key = k; last_pos = place
    return pos

def _rfm_bands(values, higher_is_better, k=5):
    """The 1..k band for each customer, best band k; ties share the better band."""
    n = len(values)
    return [k - ((p - 1) * k) // n for p in _rfm_positions(values, higher_is_better)]

def _rfm_bands_integer(values, higher_is_better, k=5):
    """Independent route: band boundaries built by integer ceilings, then looked up by rank."""
    n = len(values)
    keys = values if higher_is_better else [-v for v in values]
    pos = [1 + sum(1 for j in range(n) if keys[j] > keys[i]) for i in range(n)]
    band = [0] * (n + 1)
    for j in range(k):
        lo = (j * n + k - 1) // k
        hi = ((j + 1) * n + k - 1) // k
        for p in range(lo + 1, min(hi, n) + 1):
            band[p] = k - j
    return [band[p] for p in pos]

def rfm_scoring_impl(inp):
    rows = inp["customers"]
    if len(rows) < 5:
        raise DataError("at least five customers are required to form quintile scores")
    if len(rows) > 1000:
        raise DataError("at most a thousand customers are supported")
    names, recency, frequency, monetary = [], [], [], []
    seen = set()
    for i, row in enumerate(rows, 1):
        name = row["name"].strip() if isinstance(row.get("name"), str) else ""
        if not name or len(name) > 60:
            raise DataError("customer %d needs a name of at most 60 characters" % i)
        if name in seen:
            raise DataError("customer name %r appears more than once; every row needs a unique name" % name)
        seen.add(name)
        try:
            r = D(str(row["recency_days"])); f = D(str(row["frequency"])); m = D(str(row["monetary"]))
        except (InvalidOperation, ValueError, TypeError, KeyError):
            raise DataError("customer %d needs numeric recency_days, frequency and monetary" % i)
        if r < 0:
            raise DataError("customer %d has a negative recency_days" % i)
        if f < 1:
            raise DataError("customer %d needs a frequency of at least one" % i)
        if m < 0:
            raise DataError("customer %d has a negative monetary value" % i)
        names.append(name); recency.append(r); frequency.append(f); monetary.append(m)
    r_score = _rfm_bands(recency, higher_is_better=False)
    f_score = _rfm_bands(frequency, higher_is_better=True)
    m_score = _rfm_bands(monetary, higher_is_better=True)
    n = len(rows)
    counts = {key: 0 for key in RFM_SEGMENTS}
    detail = []
    for i in range(n):
        segment = _rfm_segment(r_score[i], f_score[i], m_score[i])
        counts[segment] += 1
        detail.append({"name": names[i], "recency_days": str(recency[i]), "frequency": str(frequency[i]),
                       "monetary": str(monetary[i]), "r_score": r_score[i], "f_score": f_score[i],
                       "m_score": m_score[i], "rfm_score": r_score[i] + f_score[i] + m_score[i],
                       "segment": segment})
    total_rfm = sum((D(row["rfm_score"]) for row in detail), D(0))
    out = {"total_customers": D(n)}
    for key in RFM_SEGMENTS:
        out["count_" + key] = D(counts[key])
    out["mean_r_score"] = sum((D(x) for x in r_score), D(0)) / n
    out["mean_f_score"] = sum((D(x) for x in f_score), D(0)) / n
    out["mean_m_score"] = sum((D(x) for x in m_score), D(0)) / n
    out["mean_rfm_score"] = total_rfm / n
    out["_appendix"] = {"customers": detail, "segment_order": list(RFM_SEGMENTS),
                        "segment_labels": dict(RFM_LABELS),
                        "scoring_rule": ("Competition ranks split into five equal-count bands; recency is "
                                         "scored in reverse, so the most recent customer scores highest. Ties "
                                         "share the better band, so band sizes can differ."),
                        "segment_rules": ("Tried in the order cannot lose, champions, loyal, potential "
                                          "loyalist, new, promising, need attention, at risk, about to sleep, "
                                          "hibernating, lost; first match wins.")}
    return out

def _rfm_ref(inp):
    recency = [D(str(r["recency_days"])) for r in inp["customers"]]
    frequency = [D(str(r["frequency"])) for r in inp["customers"]]
    monetary = [D(str(r["monetary"])) for r in inp["customers"]]
    r_score = _rfm_bands_integer(recency, higher_is_better=False)
    f_score = _rfm_bands_integer(frequency, higher_is_better=True)
    m_score = _rfm_bands_integer(monetary, higher_is_better=True)
    counts = {key: 0 for key in RFM_SEGMENTS}
    for i in range(len(recency)):
        counts[_rfm_segment(r_score[i], f_score[i], m_score[i])] += 1
    return {"total_customers": len(recency), "counts": counts,
            "mean_r_score": sum(r_score) / len(recency), "mean_f_score": sum(f_score) / len(recency),
            "mean_m_score": sum(m_score) / len(recency),
            "mean_rfm_score": (sum(r_score) + sum(f_score) + sum(m_score)) / len(recency)}

def rfm_scoring_tests(inp, impl):
    base = impl(inp)
    ref = _rfm_ref(inp)
    detail = base["_appendix"]["customers"]
    scores = [(row["r_score"], row["f_score"], row["m_score"]) for row in detail]
    counts = {key: base["count_" + key] for key in RFM_SEGMENTS}
    checks = [
        ("second_implementation_agrees",
         all(_close(base[k], ref[k]) for k in ("total_customers", "mean_r_score", "mean_f_score", "mean_m_score", "mean_rfm_score"))
         and all(int(counts[k]) == ref["counts"][k] for k in RFM_SEGMENTS),
         "integer route agrees with the Decimal route on the bands, the sizes and the means"),
        ("every_customer_has_exactly_one_segment",
         sum((base["count_" + key] for key in RFM_SEGMENTS), D(0)) == base["total_customers"] == D(len(detail)),
         "the segment sizes add up to the customer count"),
        ("scores_lie_between_one_and_five",
         all(1 <= s <= 5 for triple in scores for s in triple),
         "every recency, frequency and monetary score is a whole band from one to five"),
        ("recency_is_scored_in_reverse",
         (lambda ordered: all(ordered[k] >= ordered[k + 1] for k in range(len(ordered) - 1)))(
             [scores[i][0] for i in sorted(range(len(detail)), key=lambda i: D(detail[i]["recency_days"]))]),
         "no customer with a longer time since purchase scores above one with a shorter time"),
        ("combined_score_is_the_sum_of_the_three",
         _close(base["mean_rfm_score"], base["mean_r_score"] + base["mean_f_score"] + base["mean_m_score"]),
         "the mean combined score is the sum of the three mean scores"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def rfm_scoring_profile(inp):
    try:
        rows = inp.get("customers")
        if not isinstance(rows, list) or len(rows) < 5:
            return ["at least five customers are required to form quintile scores"]
        if len(rows) > 1000:
            return ["at most a thousand customers are supported"]
        seen = set()
        for i, row in enumerate(rows, 1):
            if not isinstance(row, dict) or not isinstance(row.get("name"), str) or not row["name"].strip():
                return ["customer %d needs a name" % i]
            if row["name"] in seen:
                return ["customer name %r appears more than once" % row["name"]]
            seen.add(row["name"])
            r = D(str(row.get("recency_days"))); f = D(str(row.get("frequency"))); m = D(str(row.get("monetary")))
            if r < 0: return ["customer %d has a negative recency_days" % i]
            if f < 1: return ["customer %d needs a frequency of at least one" % i]
            if m < 0: return ["customer %d has a negative monetary value" % i]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["customer inputs are malformed: each customer needs a name, recency_days, frequency and monetary"]

def _rfm_typing(metric):
    if metric.startswith("count_") or metric == "total_customers":
        return ("count", 0)
    return ("ratio", 2)

def rfm_scoring_caveats(out, th):
    return ["The scores come from the ranks inside this file, not from an external benchmark: the same customer can score differently in another dataset.",
            "Ties share the better band, so the five bands need not hold equal numbers of customers.",
            "The segment names come from the declared first-match rules; a different rule set gives different names for the same scores.",
            "Nothing here tests whether a segment is stable over time or differs by more than chance; it describes one snapshot."]

def rfm_scoring_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    t = ("Across " + tok("total_customers") + " customers the quintile scores put " + tok("count_champions") +
         " in Champions, " + tok("count_loyal") + " in Loyal customers, " + tok("count_at_risk") + " At risk and " +
         tok("count_lost") + " in Lost.")
    t += (" The mean recency score is " + tok("mean_r_score") + ", the mean frequency score " +
          tok("mean_f_score") + " and the mean monetary score " + tok("mean_m_score") +
          "; the combined score averages " + tok("mean_rfm_score") + " out of fifteen.")
    return t


def media_plan_impl(inp):
    population = D(str(inp["population"]))
    rows = inp["vehicles"]
    if population <= 0:
        raise DataError("population must be positive")
    if not isinstance(rows, list) or not rows:
        raise DataError("at least one vehicle is required")
    if len(rows) > 12:
        raise DataError("at most twelve vehicles are supported")
    parsed, seen = [], set()
    total_impressions = D(0); total_cost = D(0); total_grp = D(0); no_reach = D(1)
    for i, row in enumerate(rows, 1):
        name = row["name"].strip() if isinstance(row.get("name"), str) else ""
        if not name or len(name) > 60:
            raise DataError("vehicle %d needs a name of at most 60 characters" % i)
        if name in seen:
            raise DataError("vehicle name %r appears more than once" % name)
        seen.add(name)
        try:
            reach = D(str(row["reach"])); insertions = D(str(row["insertions"])); cost = D(str(row["cost"]))
        except (InvalidOperation, ValueError, TypeError, KeyError):
            raise DataError("vehicle %d needs numeric reach, insertions and cost" % i)
        if reach <= 0 or reach > population:
            raise DataError("vehicle %d reach must be positive and cannot exceed the population" % i)
        if insertions <= 0:
            raise DataError("vehicle %d insertions must be positive" % i)
        if cost < 0:
            raise DataError("vehicle %d cost must be non-negative" % i)
        parsed.append((name, reach, insertions, cost))
    vehicles = D(len(parsed))
    out = {}
    for i, (name, reach, insertions, cost) in enumerate(parsed, 1):
        share = reach / population
        impressions = reach * insertions
        grp = share * insertions * D(100)
        out["reach_%d" % i] = reach
        out["reach_pct_%d" % i] = share
        out["impressions_%d" % i] = impressions
        out["grp_%d" % i] = grp
        out["cpm_%d" % i] = cost / impressions * D(1000)
        out["cpp_%d" % i] = cost / grp
        total_impressions += impressions; total_cost += cost; total_grp += grp
        no_reach *= (D(1) - share)
    net_reach = population * (D(1) - no_reach)
    out.update({"vehicles": vehicles, "population": population, "total_impressions": total_impressions,
                "total_grp": total_grp, "total_cost": total_cost,
                "blended_cpm": total_cost / total_impressions * D(1000),
                "net_reach": net_reach,
                "average_frequency": total_impressions / net_reach})
    return out

def _media_ref(inp):
    population = float(D(str(inp["population"])))
    rows = inp["vehicles"]
    no_reach = 1.0
    impressions = cost = grp = 0.0
    first = None
    for i, row in enumerate(rows, 1):
        reach = float(D(str(row["reach"]))); ins = float(D(str(row["insertions"]))); c = float(D(str(row["cost"])))
        share = reach / population
        imp = reach * ins
        g = share * ins * 100.0
        if first is None: first = (reach, share, imp, g, c / imp * 1000.0, c / g)
        impressions += imp; cost += c; grp += g; no_reach *= (1.0 - share)
    net = population * (1.0 - no_reach)
    return {"vehicles": len(rows), "total_impressions": impressions, "total_grp": grp, "total_cost": cost,
            "blended_cpm": cost / impressions * 1000.0, "net_reach": net,
            "average_frequency": impressions / net, "first": first}

def media_plan_tests(inp, impl):
    base, ref = impl(inp), _media_ref(inp)
    population = D(str(inp["population"]))
    rows = inp["vehicles"]
    reaches = [D(str(r["reach"])) for r in rows]
    insertions = [D(str(r["insertions"])) for r in rows]
    checks = [
        ("second_implementation_agrees",
         all(_close(base[k], ref[k]) for k in ("vehicles", "total_impressions", "total_grp", "total_cost",
                                               "blended_cpm", "net_reach", "average_frequency")),
         "float route agrees with the Decimal route"),
        ("grp_is_reach_share_times_frequency",
         all(_close(base["grp_%d" % i], reaches[i - 1] / population * insertions[i - 1] * D(100))
             for i in range(1, len(rows) + 1)),
         "rating points are the reach share times the average frequency times one hundred"),
        ("impressions_are_reach_times_frequency",
         all(_close(base["impressions_%d" % i], reaches[i - 1] * insertions[i - 1])
             for i in range(1, len(rows) + 1)),
         "gross impressions are the reach times the average frequency"),
        ("total_grp_is_the_sum_of_the_vehicle_grp",
         _close(base["total_grp"], sum((base["grp_%d" % i] for i in range(1, len(rows) + 1)), D(0))),
         "the plan's rating points are the sum of its vehicles'"),
        ("net_reach_lies_between_the_largest_vehicle_and_the_sum",
         max(reaches) <= base["net_reach"] <= sum(reaches, D(0)),
         "under random duplication the combined reach cannot beat the sum or fall below the largest vehicle"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def media_plan_profile(inp):
    try:
        population = D(str(inp.get("population")))
        rows = inp.get("vehicles")
        if population <= 0:
            return ["population must be positive"]
        if not isinstance(rows, list) or not rows:
            return ["at least one vehicle is required"]
        if len(rows) > 12:
            return ["at most twelve vehicles are supported"]
        seen = set()
        for i, row in enumerate(rows, 1):
            if not isinstance(row, dict) or not isinstance(row.get("name"), str) or not row["name"].strip():
                return ["vehicle %d needs a name" % i]
            if row["name"] in seen:
                return ["vehicle name %r appears more than once" % row["name"]]
            seen.add(row["name"])
            reach = D(str(row.get("reach"))); ins = D(str(row.get("insertions"))); cost = D(str(row.get("cost")))
            if reach <= 0 or reach > population:
                return ["vehicle %d reach must be positive and cannot exceed the population" % i]
            if ins <= 0:
                return ["vehicle %d insertions must be positive" % i]
            if cost < 0:
                return ["vehicle %d cost must be non-negative" % i]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["media inputs are malformed: population and each vehicle's name, reach, insertions and cost are required"]

def _media_typing(metric):
    if metric.startswith("reach_pct_"):
        return ("rate", 4)
    if metric in ("vehicles", "population", "net_reach") or metric.startswith("reach_") or metric.startswith("impressions_"):
        return ("count", 0)
    if metric == "average_frequency":
        return ("ratio", 2)
    if metric == "total_grp" or metric.startswith("grp_"):
        return ("ratio", 1)
    return ("currency", 2)

def media_plan_caveats(out, th):
    return ["Reach, average frequency and cost are the figures you declare for each vehicle; the method does not read a media owner's or platform's data.",
            "The combined net reach uses the random-duplication formula, which assumes the audiences of different vehicles overlap only by chance; real overlap is usually higher, so the estimate is an upper bound.",
            "Rating points add up across vehicles but reach does not: a plan can double its points without doubling its audience.",
            "No seasonality, wear-out, scheduling, negotiation or response curve is modelled, and the method does not say which plan to buy."]

def media_plan_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    t = ("The plan buys " + tok("total_grp") + " gross rating points for " + tok("total_cost") +
         ", a blended cost of " + tok("blended_cpm") + " per thousand impressions, on the first vehicle at " +
         tok("cpp_1") + " per rating point.")
    t += (" Under random duplication the vehicles together reach " + tok("net_reach") + " people, an average frequency of " +
          tok("average_frequency") + ".")
    return t


# ---------- Marketing measurement additions (B-131) ----------

def market_share_impl(inp):
    firm = D(str(inp["firm_sales"])); market = D(str(inp["market_sales"]))
    if market <= 0:
        raise DataError("market_sales must be positive")
    if firm < 0 or firm > market:
        raise DataError("firm_sales must be non-negative and cannot exceed market_sales")
    out = {"firm_sales": firm, "market_sales": market, "market_share": firm / market}
    prior_firm = _optional_decimal(inp, "prior_firm_sales")
    prior_market = _optional_decimal(inp, "prior_market_sales")
    if (prior_firm is None) != (prior_market is None):
        raise DataError("declare both prior_firm_sales and prior_market_sales, or neither")
    if prior_firm is not None:
        if prior_market <= 0:
            raise DataError("prior_market_sales must be positive")
        if prior_firm < 0 or prior_firm > prior_market:
            raise DataError("prior_firm_sales must be non-negative and cannot exceed prior_market_sales")
        prior_share = prior_firm / prior_market
        out["prior_share"] = prior_share
        out["share_change"] = out["market_share"] - prior_share
        out["firm_growth"] = (firm / prior_firm - D(1)) if prior_firm > 0 else None
        if out["firm_growth"] is None:
            out.pop("firm_growth")
        out["market_growth"] = market / prior_market - D(1)
    customers = _optional_decimal(inp, "customers")
    population = _optional_decimal(inp, "target_population")
    if (customers is None) != (population is None):
        raise DataError("declare both customers and target_population, or neither")
    if customers is not None:
        if population <= 0:
            raise DataError("target_population must be positive")
        if customers < 0 or customers > population:
            raise DataError("customers must be non-negative and cannot exceed target_population")
        out["customers"] = customers
        out["target_population"] = population
        out["penetration_rate"] = customers / population
    rival = _optional_decimal(inp, "largest_competitor_sales")
    if rival is not None:
        if rival <= 0:
            raise DataError("largest_competitor_sales must be positive")
        out["largest_competitor_sales"] = rival
        out["relative_market_share"] = firm / rival
        out["competitor_share"] = rival / market
    return out

def _market_share_ref(inp):
    firm = float(D(str(inp["firm_sales"]))); market = float(D(str(inp["market_sales"])))
    res = {"market_share": firm / market}
    if str(inp.get("prior_firm_sales", "")).strip() and str(inp.get("prior_market_sales", "")).strip():
        res["share_change"] = firm / market - float(D(str(inp["prior_firm_sales"]))) / float(D(str(inp["prior_market_sales"])))
    if str(inp.get("customers", "")).strip() and str(inp.get("target_population", "")).strip():
        res["penetration_rate"] = float(D(str(inp["customers"]))) / float(D(str(inp["target_population"])))
    if str(inp.get("largest_competitor_sales", "")).strip():
        res["relative_market_share"] = firm / float(D(str(inp["largest_competitor_sales"])))
    return res

def market_share_tests(inp, impl):
    base, ref = impl(inp), _market_share_ref(inp)
    firm = D(str(inp["firm_sales"])); market = D(str(inp["market_sales"]))
    checks = [
        ("second_implementation_agrees", all(_close(base[k], ref[k]) for k in ref), "float route agrees with the Decimal route"),
        ("share_is_firm_sales_over_market_sales", _close(base["market_share"], firm / market), "share is the firm's sales over the whole market"),
        ("share_lies_between_zero_and_one", D(0) <= base["market_share"] <= D(1), "a share cannot exceed the market it is drawn from"),
        ("share_change_is_the_difference_of_shares",
         ("share_change" not in base) or _close(base["share_change"], base["market_share"] - base["prior_share"]),
         "the change is this period's share minus last period's"),
        ("relative_share_is_the_firm_over_the_largest_rival",
         ("relative_market_share" not in base) or _close(base["relative_market_share"], base["firm_sales"] / base["largest_competitor_sales"]),
         "relative share compares the firm with the largest declared competitor"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def market_share_profile(inp):
    try:
        market = D(str(inp.get("market_sales"))); firm = D(str(inp.get("firm_sales")))
        if market <= 0: return ["market_sales must be positive"]
        if firm < 0 or firm > market: return ["firm_sales must be non-negative and cannot exceed market_sales"]
        for a, b in (("prior_firm_sales", "prior_market_sales"), ("customers", "target_population")):
            x = _optional_decimal(inp, a); y = _optional_decimal(inp, b)
            if (x is None) != (y is None): return ["declare both %s and %s, or neither" % (a, b)]
            if x is not None and y is not None and y <= 0: return ["%s must be positive" % b]
        rival = _optional_decimal(inp, "largest_competitor_sales")
        if rival is not None and rival <= 0: return ["largest_competitor_sales must be positive"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["market inputs are malformed: firm_sales and market_sales are required numbers"]

def _market_share_typing(metric):
    if metric in ("firm_sales", "market_sales", "largest_competitor_sales"):
        return ("currency", 2)
    if metric in ("customers", "target_population"):
        return ("count", 0)
    if metric == "relative_market_share":
        return ("ratio", 2)
    return ("rate", 4)

def market_share_caveats(out, th):
    return ["Firm and market sales are the figures you declare, from the same definition and the same period; a retailer's and a manufacturer's sales are not the same market.",
            "The market boundary is your choice: widening or narrowing it changes the share without any sales changing.",
            "Penetration is customers divided by the declared target population, not buyer behaviour measured over time, and a customer may count in more than one category.",
            "No competitor data is retrieved and no share is estimated; the largest rival is one you name."]

def market_share_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    t = ("On the declared market, the firm holds " + tok("market_share") + " of sales (" + tok("firm_sales") +
         " of " + tok("market_sales") + ").")
    if "share_change" in out:
        t += (" That is a change of " + tok("share_change") + " from the previous period, when the share was " +
              tok("prior_share") + ".")
    if "penetration_rate" in out:
        t += (" Of the declared target population, " + tok("customers") + " customers buy, a penetration rate of " +
              tok("penetration_rate") + ".")
    if "relative_market_share" in out:
        t += (" Against the largest declared competitor the firm's relative share is " + tok("relative_market_share") + ".")
    return t


def clv_model_impl(inp):
    margin = D(str(inp["margin_per_period"])); churn = D(str(inp["churn_rate"]))
    horizon = int(D(str(inp.get("horizon_periods", "12"))))
    rate = _optional_decimal(inp, "discount_rate")
    rate = D(0) if rate is None else rate
    if margin <= 0:
        raise DataError("margin_per_period must be positive")
    if not (D(0) < churn <= D(1)):
        raise DataError("churn_rate must be in (0, 1]")
    if rate < 0:
        raise DataError("discount_rate must be non-negative")
    if not (1 <= horizon <= 60):
        raise DataError("horizon_periods must be between one and sixty")
    keep = D(1) - churn
    discounted, undiscounted = D(0), D(0)
    survival = D(1)
    for t in range(1, horizon + 1):
        undiscounted += margin * survival
        discounted += margin * survival / ((D(1) + rate) ** t)
        survival *= keep
    out = {"margin_per_period": margin, "churn_rate": churn, "horizon_periods": D(horizon),
           "discount_rate": rate, "clv_undiscounted": undiscounted, "clv_discounted": discounted}
    if rate > 0:
        out["discount_effect"] = undiscounted - discounted
    cac = _optional_decimal(inp, "acquisition_cost")
    if cac is not None:
        if cac <= 0:
            raise DataError("acquisition_cost must be positive when declared")
        running = D(0); payback = None; survival = D(1)
        for t in range(1, horizon + 1):
            running += margin * survival
            survival *= keep
            if payback is None and running >= cac:
                payback = D(t)
        out["acquisition_cost"] = cac
        out["ltv_cac"] = discounted / cac
        out["payback_within_horizon"] = D(1) if payback is not None else D(0)
        if payback is not None:
            out["payback_periods"] = payback
    return out

def _clv_ref(inp):
    margin = float(D(str(inp["margin_per_period"]))); churn = float(D(str(inp["churn_rate"])))
    horizon = int(D(str(inp.get("horizon_periods", "12"))))
    rate = inp.get("discount_rate")
    rate = 0.0 if rate in (None, "") else float(D(str(rate)))
    disc = undisc = 0.0; survival = 1.0
    for t in range(1, horizon + 1):
        undisc += margin * survival
        disc += margin * survival / (1.0 + rate) ** t
        survival *= (1.0 - churn)
    return {"clv_undiscounted": undisc, "clv_discounted": disc}

def clv_model_tests(inp, impl):
    base, ref = impl(inp), _clv_ref(inp)
    margin = D(str(inp["margin_per_period"])); churn = D(str(inp["churn_rate"]))
    horizon = int(D(str(inp.get("horizon_periods", "12"))))
    keep = D(1) - churn
    closed = margin * horizon if churn == 1 else margin * (D(1) - keep ** horizon) / churn
    one = impl({**inp, "horizon_periods": "1"})
    checks = [
        ("second_implementation_agrees",
         _close(base["clv_undiscounted"], ref["clv_undiscounted"]) and _close(base["clv_discounted"], ref["clv_discounted"]),
         "float route agrees with the Decimal route"),
        ("undiscounted_value_is_the_closed_form_annuity",
         _close(base["clv_undiscounted"], closed),
         "the undiscounted value equals margin times the finite geometric sum of survival"),
        ("discounting_never_increases_the_value",
         base["clv_discounted"] <= base["clv_undiscounted"],
         "a positive discount rate can only lower the value"),
        ("a_single_period_is_the_margin_over_one_plus_the_rate",
         _close(one["clv_discounted"], margin / (D(1) + base["discount_rate"])),
         "with a one-period horizon the value is the margin discounted once"),
        ("payback_is_the_first_period_whose_cumulative_margin_covers_the_cost",
         ("payback_periods" not in base) or _cumulative_covers(margin, churn, horizon, int(base["payback_periods"]), base["acquisition_cost"]),
         "the reported payback is the first period at which cumulative margin reaches the acquisition cost"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def _cumulative_covers(margin, churn, horizon, payback, cost):
    if not (1 <= payback <= horizon):
        return False
    running = D(0); survival = D(1)
    for t in range(1, horizon + 1):
        running += margin * survival; survival *= (D(1) - churn)
        if t == payback:
            return running >= cost
    return False

def clv_model_profile(inp):
    try:
        margin = D(str(inp.get("margin_per_period"))); churn = D(str(inp.get("churn_rate")))
        horizon = int(D(str(inp.get("horizon_periods", "12"))))
        rate = inp.get("discount_rate"); rate = D(0) if rate in (None, "") else D(str(rate))
        if margin <= 0: return ["margin_per_period must be positive"]
        if not (D(0) < churn <= D(1)): return ["churn_rate must be in (0, 1]"]
        if rate < 0: return ["discount_rate must be non-negative"]
        if not (1 <= horizon <= 60): return ["horizon_periods must be between one and sixty"]
        cac = _optional_decimal(inp, "acquisition_cost")
        if cac is not None and cac <= 0: return ["acquisition_cost must be positive when declared"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["customer-value inputs are malformed: margin_per_period and churn_rate are required numbers"]

def _clv_typing(metric):
    if metric in ("horizon_periods", "payback_within_horizon", "payback_periods"):
        return ("count", 0)
    if metric in ("churn_rate", "discount_rate"):
        return ("rate", 4)
    if metric == "ltv_cac":
        return ("ratio", 2)
    return ("currency", 2)

def clv_model_caveats(out, th):
    return ["The margin, churn and discount rate are declared constants; a real customer's margin and churn change over time and by segment.",
            "Value is summed over the declared horizon only, so a longer horizon raises the figure; the horizon is a choice, not a fact.",
            "Churn is a constant probability per period, which cannot represent a cohort whose risk rises or falls.",
            "Payback is measured in the same periods as the margin and is not discounted, so it is a cash-timing view, not a value."]

def clv_model_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    t = ("Over a declared horizon of " + tok("horizon_periods") + " periods at a " + tok("discount_rate") +
         " discount rate, a customer worth " + tok("margin_per_period") + " of margin per period and churning at " +
         tok("churn_rate") + " is worth " + tok("clv_discounted") + " today.")
    t += " Undiscounted, the same customer is worth " + tok("clv_undiscounted") + "."
    if "ltv_cac" in out:
        t += (" At the declared acquisition cost of " + tok("acquisition_cost") + ", value per unit of acquisition cost is " +
              tok("ltv_cac") + " and the cost is recovered in " + tok("payback_periods") + " periods.")
    return t


def customer_profitability_impl(inp):
    rows = inp["segments"]
    if not isinstance(rows, list) or len(rows) < 2:
        raise DataError("at least two segments are required")
    if len(rows) > 50:
        raise DataError("at most fifty segments are supported")
    threshold = _optional_decimal(inp, "concentration_threshold")
    threshold = D("0.8") if threshold is None else threshold
    if not (D(0) < threshold <= D(1)):
        raise DataError("concentration_threshold must be in (0, 1]")
    parsed, seen = [], set()
    for i, row in enumerate(rows, 1):
        name = row["name"].strip() if isinstance(row.get("name"), str) else ""
        if not name or len(name) > 60:
            raise DataError("segment %d needs a name of at most 60 characters" % i)
        if name in seen:
            raise DataError("segment name %r appears more than once" % name)
        seen.add(name)
        try:
            revenue = D(str(row["revenue"])); direct = D(str(row["direct_cost"]))
        except (InvalidOperation, ValueError, TypeError, KeyError):
            raise DataError("segment %d needs numeric revenue and direct_cost" % i)
        allocated = _optional_decimal(row, "allocated_cost")
        allocated = D(0) if allocated is None else allocated
        if revenue < 0 or direct < 0 or allocated < 0:
            raise DataError("segment %d has a negative revenue or cost" % i)
        parsed.append((name, revenue, direct, allocated))
    total_revenue = sum((p[1] for p in parsed), D(0))
    if total_revenue <= 0:
        raise DataError("total revenue must be positive")
    total_cost = sum((p[2] + p[3] for p in parsed), D(0))
    total_profit = total_revenue - total_cost
    out = {"segments": D(len(parsed)), "total_revenue": total_revenue, "total_cost": total_cost,
           "total_profit": total_profit, "overall_margin": total_profit / total_revenue}
    profits = []
    for i, (name, revenue, direct, allocated) in enumerate(parsed, 1):
        profit = revenue - direct - allocated
        out["revenue_%d" % i] = revenue
        out["profit_%d" % i] = profit
        out["margin_%d" % i] = profit / revenue if revenue > 0 else None
        if out["margin_%d" % i] is None:
            out.pop("margin_%d" % i)
        out["profit_share_%d" % i] = profit / total_profit if total_profit != 0 else None
        if out["profit_share_%d" % i] is None:
            out.pop("profit_share_%d" % i)
        profits.append(profit)
    out["profitable"] = D(sum(1 for p in profits if p > 0))
    out["unprofitable"] = D(sum(1 for p in profits if p < 0))
    ordered = sorted(profits, key=lambda p: -p)
    running = D(0); needed = None
    for i, p in enumerate(ordered, 1):
        running += p
        if total_profit > 0 and needed is None and running >= total_profit * threshold:
            needed = i
    out["segments_for_threshold"] = D(needed if needed is not None else len(ordered))
    out["concentration_threshold"] = threshold
    out["_appendix"] = {"segments": [{"name": name, "revenue": str(revenue), "direct_cost": str(direct),
                                      "allocated_cost": str(allocated), "profit": str(revenue - direct - allocated)}
                                     for name, revenue, direct, allocated in parsed],
                        "ranked_by_profit": [name for name, _, _, _ in sorted(parsed, key=lambda p: -(p[1] - p[2] - p[3]))]}
    return out

def _customer_profitability_ref(inp):
    rev = [float(D(str(r["revenue"]))) for r in inp["segments"]]
    cost = [float(D(str(r["direct_cost"]))) + float(D(str(r.get("allocated_cost") or 0))) for r in inp["segments"]]
    profit = [r - c for r, c in zip(rev, cost)]
    total_r, total_p = sum(rev), sum(profit)
    return {"segments": len(rev), "total_revenue": total_r, "total_profit": total_p,
            "overall_margin": total_p / total_r, "profitable": sum(1 for p in profit if p > 0),
            "unprofitable": sum(1 for p in profit if p < 0)}

def customer_profitability_tests(inp, impl):
    base, ref = impl(inp), _customer_profitability_ref(inp)
    rows = inp["segments"]; n = len(rows)
    rev = [D(str(r["revenue"])) for r in rows]
    cost = [D(str(r["direct_cost"])) + (D(str(r["allocated_cost"])) if str(r.get("allocated_cost") or "").strip() else D(0)) for r in rows]
    profit = [rev[i] - cost[i] for i in range(n)]
    shares = [base["profit_share_%d" % (i + 1)] for i in range(n) if "profit_share_%d" % (i + 1) in base]
    ordered = sorted(profit, key=lambda p: -p)
    running = D(0); needed = 0
    for i, p in enumerate(ordered, 1):
        running += p
        if base["total_profit"] > 0 and needed == 0 and running >= base["total_profit"] * base["concentration_threshold"]:
            needed = i
    checks = [
        ("second_implementation_agrees",
         all(_close(base[k], ref[k]) for k in ref), "float route agrees with the Decimal route"),
        ("profit_is_revenue_minus_direct_and_allocated_cost",
         all(_close(base["profit_%d" % (i + 1)], profit[i]) for i in range(n)),
         "each segment's profit is its revenue less both declared cost lines"),
        ("total_profit_is_the_sum_of_the_segments",
         _close(base["total_profit"], sum(profit, D(0))), "the total is the sum of the segment profits"),
        ("profit_shares_sum_to_one_when_the_total_is_positive",
         (base["total_profit"] <= 0) or _close(sum(shares, D(0)), D(1)),
         "when the plan is profitable, the segment shares cover it exactly"),
        ("concentration_count_is_the_smallest_group_reaching_the_threshold",
         int(base["segments_for_threshold"]) == (needed if needed else n),
         "the reported count is the smallest number of most profitable segments that reach the declared share"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def customer_profitability_profile(inp):
    try:
        rows = inp.get("segments")
        if not isinstance(rows, list) or len(rows) < 2: return ["at least two segments are required"]
        if len(rows) > 50: return ["at most fifty segments are supported"]
        threshold = _optional_decimal(inp, "concentration_threshold")
        if threshold is not None and not (D(0) < threshold <= D(1)):
            return ["concentration_threshold must be in (0, 1]"]
        seen = set()
        for i, row in enumerate(rows, 1):
            if not isinstance(row, dict) or not isinstance(row.get("name"), str) or not row["name"].strip():
                return ["segment %d needs a name" % i]
            if row["name"] in seen: return ["segment name %r appears more than once" % row["name"]]
            seen.add(row["name"])
            revenue = D(str(row.get("revenue"))); direct = D(str(row.get("direct_cost")))
            allocated = _optional_decimal(row, "allocated_cost")
            if revenue < 0 or direct < 0 or (allocated is not None and allocated < 0):
                return ["segment %d has a negative revenue or cost" % i]
        if sum((D(str(r["revenue"])) for r in rows), D(0)) <= 0:
            return ["total revenue must be positive"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["profitability inputs are malformed: each segment needs a name, revenue and direct_cost"]

def _customer_profitability_typing(metric):
    if metric in ("segments", "profitable", "unprofitable", "segments_for_threshold"):
        return ("count", 0)
    if metric.startswith("margin_") or metric in ("overall_margin", "concentration_threshold"):
        return ("rate", 4)
    if metric.startswith("profit_share_"):
        return ("ratio", 4)
    return ("currency", 2)

def customer_profitability_caveats(out, th):
    return ["Revenue and both cost lines are the figures you declare; allocating a shared cost is a choice that changes which segments look profitable.",
            "Direct and allocated costs are treated as fully variable with the segment; a fixed cost left out of the rows is not recovered anywhere.",
            "Profit here is contribution after the declared costs, not accounting profit: no depreciation, tax or capital charge is applied.",
            "The concentration count describes this snapshot of declared segments; it does not test whether the concentration is stable or significant."]

def customer_profitability_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    t = ("Across " + tok("segments") + " declared segments, revenue of " + tok("total_revenue") + " and declared costs of " +
         tok("total_cost") + " leave " + tok("total_profit") + ", an overall margin of " + tok("overall_margin") + ".")
    t += (" The profitable segments number " + tok("profitable") + " and the unprofitable " + tok("unprofitable") +
          "; the smallest group of leading segments that reaches the declared profit share contains " +
          tok("segments_for_threshold") + " of them.")
    return t


# ---------- Accounting and operations shelf (B-110) ----------

def standard_cost_variances_impl(inp):
    units = D(str(inp["actual_units"]))
    sq = units * D(str(inp["standard_material_per_unit"]))
    sp = D(str(inp["standard_material_price"]))
    aq = D(str(inp["actual_material_quantity"]))
    ap = D(str(inp["actual_material_price"]))
    sh = units * D(str(inp["standard_hours_per_unit"]))
    sr = D(str(inp["standard_labour_rate"]))
    ah = D(str(inp["actual_hours"]))
    ar = D(str(inp["actual_labour_rate"]))
    if units <= 0:
        raise DataError("actual_units must be positive")
    for key, value in (("standard_material_per_unit", inp["standard_material_per_unit"]),
                       ("standard_material_price", sp), ("actual_material_quantity", aq),
                       ("actual_material_price", ap), ("standard_hours_per_unit", inp["standard_hours_per_unit"]),
                       ("standard_labour_rate", sr), ("actual_hours", ah), ("actual_labour_rate", ar)):
        if D(str(value)) < 0:
            raise DataError(key + " must be non-negative")
    mat_price = aq * (ap - sp)
    mat_usage = sp * (aq - sq)
    lab_rate = ah * (ar - sr)
    lab_eff = sr * (ah - sh)
    out = {"actual_units": units, "standard_material_quantity": sq, "standard_hours": sh,
           "material_price_variance": mat_price, "material_usage_variance": mat_usage,
           "labour_rate_variance": lab_rate, "labour_efficiency_variance": lab_eff,
           "material_variance": mat_price + mat_usage, "labour_variance": lab_rate + lab_eff}
    total = mat_price + mat_usage + lab_rate + lab_eff
    vo_rate = _optional_decimal(inp, "standard_variable_overhead_rate")
    if vo_rate is not None:
        avo = D(str(inp["actual_variable_overhead"]))
        if vo_rate < 0 or avo < 0:
            raise DataError("variable overhead inputs must be non-negative")
        out["standard_variable_overhead_rate"] = vo_rate
        out["variable_overhead_spending_variance"] = avo - ah * vo_rate
        out["variable_overhead_efficiency_variance"] = vo_rate * (ah - sh)
        total += out["variable_overhead_spending_variance"] + out["variable_overhead_efficiency_variance"]
    budgeted = _optional_decimal(inp, "budgeted_fixed_overhead")
    if budgeted is not None:
        actual_foh = D(str(inp["actual_fixed_overhead"]))
        denominator = D(str(inp["denominator_hours"]))
        if budgeted < 0 or actual_foh < 0 or denominator <= 0:
            raise DataError("fixed overhead inputs must be non-negative and denominator_hours positive")
        rate = budgeted / denominator
        applied = sh * rate
        out["standard_fixed_overhead_rate"] = rate
        out["fixed_overhead_spending_variance"] = actual_foh - budgeted
        out["fixed_overhead_volume_variance"] = budgeted - applied
        total += out["fixed_overhead_spending_variance"] + out["fixed_overhead_volume_variance"]
    out["total_variance"] = total
    return out

def _scv_ref(inp):
    units = float(D(str(inp["actual_units"])))
    sq = units * float(D(str(inp["standard_material_per_unit"])))
    sp = float(D(str(inp["standard_material_price"])))
    aq = float(D(str(inp["actual_material_quantity"])))
    ap = float(D(str(inp["actual_material_price"])))
    sh = units * float(D(str(inp["standard_hours_per_unit"])))
    sr = float(D(str(inp["standard_labour_rate"])))
    ah = float(D(str(inp["actual_hours"])))
    ar = float(D(str(inp["actual_labour_rate"])))
    mat = aq * ap - sq * sp
    lab = ah * ar - sh * sr
    return {"material_variance": mat, "labour_variance": lab, "total_variance": mat + lab}

def standard_cost_variances_tests(inp, impl):
    base, ref = impl(inp), _scv_ref(inp)
    units = D(str(inp["actual_units"]))
    sq = units * D(str(inp["standard_material_per_unit"]))
    sp = D(str(inp["standard_material_price"]))
    aq = D(str(inp["actual_material_quantity"]))
    ap = D(str(inp["actual_material_price"]))
    sh = units * D(str(inp["standard_hours_per_unit"]))
    sr = D(str(inp["standard_labour_rate"]))
    ah = D(str(inp["actual_hours"]))
    ar = D(str(inp["actual_labour_rate"]))
    fixed = [base[k] for k in ("material_price_variance", "material_usage_variance", "labour_rate_variance",
                               "labour_efficiency_variance", "variable_overhead_spending_variance",
                               "variable_overhead_efficiency_variance", "fixed_overhead_spending_variance",
                               "fixed_overhead_volume_variance") if k in base]
    checks = [
        ("second_implementation_agrees", _close(base["material_variance"], ref["material_variance"], rel=1e-9)
         and _close(base["labour_variance"], ref["labour_variance"], rel=1e-9), "float route agrees with the Decimal route"),
        ("material_price_and_usage_sum_to_the_material_variance",
         _close(base["material_price_variance"] + base["material_usage_variance"], aq * ap - sq * sp), "the price and usage variances add to actual material cost less standard material cost"),
        ("labour_rate_and_efficiency_sum_to_the_labour_variance",
         _close(base["labour_rate_variance"] + base["labour_efficiency_variance"], ah * ar - sh * sr), "the rate and efficiency variances add to actual labour cost less standard labour cost"),
        ("fixed_overhead_volume_is_budget_applied",
         "fixed_overhead_volume_variance" not in base
         or _close(base["fixed_overhead_volume_variance"], D(str(inp["budgeted_fixed_overhead"])) - sh * base["standard_fixed_overhead_rate"]),
         "the volume variance is the budgeted overhead less the overhead applied to actual output"),
        ("total_variance_is_the_sum_of_the_reported_variances", _close(base["total_variance"], sum(fixed, D(0))), "the total is the sum of the variances reported"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def standard_cost_variances_profile(inp):
    try:
        units = D(str(inp["actual_units"]))
        if units <= 0:
            return ["actual_units must be positive"]
        for key in ("standard_material_per_unit", "standard_material_price", "actual_material_quantity",
                    "actual_material_price", "standard_hours_per_unit", "standard_labour_rate",
                    "actual_hours", "actual_labour_rate"):
            if D(str(inp[key])) < 0:
                return [key + " must be non-negative"]
        vo = _optional_decimal(inp, "standard_variable_overhead_rate")
        if vo is not None:
            if vo < 0 or D(str(inp.get("actual_variable_overhead", "0"))) < 0:
                return ["variable overhead inputs must be non-negative"]
            if "actual_variable_overhead" not in inp:
                return ["actual_variable_overhead is required when a standard variable overhead rate is declared"]
        budgeted = _optional_decimal(inp, "budgeted_fixed_overhead")
        if budgeted is not None:
            if budgeted < 0 or D(str(inp.get("actual_fixed_overhead", "0"))) < 0:
                return ["fixed overhead inputs must be non-negative"]
            if D(str(inp.get("denominator_hours", "0"))) <= 0:
                return ["denominator_hours must be positive when fixed overhead is declared"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError) as e:
        return ["standard-cost inputs are malformed: actual_units, the standard and actual material figures, and the standard and actual labour figures are required"]

def _scv_typing(metric):
    if metric in ("actual_units", "standard_material_quantity", "standard_hours"):
        return ("units", 2)
    if metric in ("standard_material_per_unit",):
        return ("ratio", 4)
    if metric in ("standard_hours_per_unit",):
        return ("periods", 4)
    return ("currency", 2)

def standard_cost_variances_caveats(out, th):
    return ["A positive variance means actual cost was higher than standard for the output achieved (unfavourable); a negative variance is favourable.",
            "The standard quantities and prices are the ones you declare; the method does not set standards or judge whether they are attainable.",
            "Only the variances named are computed: material price and usage, labour rate and efficiency, and (when declared) variable and fixed overhead. Mix, yield, sales and planning variances are not modelled."]

def standard_cost_variances_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    t = ("For " + tok("actual_units") + " units, the material price variance is " + tok("material_price_variance") +
         " and the material usage variance is " + tok("material_usage_variance") + "; the labour rate variance is " +
         tok("labour_rate_variance") + " and the labour efficiency variance is " + tok("labour_efficiency_variance") + ".")
    t += " The total variance is " + tok("total_variance") + ", with a positive figure unfavourable."
    return t


def inventory_policy_impl(inp):
    demand = D(str(inp["annual_demand"]))
    order_cost = D(str(inp["order_cost"]))
    holding = D(str(inp["holding_cost_per_unit"]))
    lead = D(str(inp["lead_time_days"]))
    days = D(str(inp.get("days_per_year", "365")))
    service = _optional_decimal(inp, "service_level")
    sd = _optional_decimal(inp, "daily_demand_sd")
    if demand <= 0:
        raise DataError("annual_demand must be positive")
    if order_cost <= 0:
        raise DataError("order_cost must be positive")
    if holding <= 0:
        raise DataError("holding_cost_per_unit must be positive")
    if lead <= 0:
        raise DataError("lead_time_days must be positive")
    if days <= 0:
        raise DataError("days_per_year must be positive")
    if service is not None and not (0 < service < 1):
        raise DataError("service_level must be greater than zero and below one")
    if sd is not None and sd < 0:
        raise DataError("daily_demand_sd must be non-negative")
    eoq = (2 * demand * order_cost / holding).sqrt()
    orders = demand / eoq
    cycle = eoq / 2
    z = D(0)
    safety = D(0)
    if service is not None:
        z = D(repr(statistics.NormalDist().inv_cdf(float(service))))
    if sd is not None and service is not None:
        safety = z * sd * lead.sqrt()
    daily = demand / days
    reorder = daily * lead + safety
    average = cycle + safety
    ordering = orders * order_cost
    carrying = average * holding
    return {"annual_demand": demand, "order_cost": order_cost, "holding_cost_per_unit": holding,
            "lead_time_days": lead, "days_per_year": days, "service_level": service,
            "daily_demand_sd": sd, "safety_factor": z,
            "economic_order_quantity": eoq, "orders_per_year": orders, "cycle_stock": cycle,
            "safety_stock": safety, "reorder_point": reorder, "average_inventory": average,
            "annual_ordering_cost": ordering, "annual_holding_cost": carrying,
            "total_annual_cost": ordering + carrying,
            "daily_demand": daily}

def _inventory_ref(inp):
    demand = float(D(str(inp["annual_demand"])))
    order_cost = float(D(str(inp["order_cost"])))
    holding = float(D(str(inp["holding_cost_per_unit"])))
    eoq = (2 * demand * order_cost / holding) ** 0.5
    service = _optional_decimal(inp, "service_level")
    sd = _optional_decimal(inp, "daily_demand_sd")
    safety = 0.0
    if service is not None and sd is not None:
        safety = statistics.NormalDist().inv_cdf(float(service)) * float(sd) * float(D(str(inp["lead_time_days"]))) ** 0.5
    return {"economic_order_quantity": eoq,
            "total_annual_cost": (demand / eoq) * order_cost + (eoq / 2 + safety) * holding}

def inventory_policy_tests(inp, impl):
    base, ref = impl(inp), _inventory_ref(inp)
    demand = D(str(inp["annual_demand"]))
    order_cost = D(str(inp["order_cost"]))
    holding = D(str(inp["holding_cost_per_unit"]))
    bigger = impl({**inp, "annual_demand": str(demand * 2)})
    worse = base["annual_ordering_cost"] * D("1.1") + (base["cycle_stock"] * D("1.1")) * holding
    checks = [
        ("second_implementation_agrees", _close(base["economic_order_quantity"], ref["economic_order_quantity"], rel=1e-6)
         and _close(base["total_annual_cost"], ref["total_annual_cost"], rel=1e-6), "float route agrees with the Decimal route"),
        ("eoq_is_the_square_root_formula",
         _close(base["economic_order_quantity"] ** 2, 2 * demand * order_cost / holding), "the order quantity squares to twice demand times order cost over holding cost"),
        ("doubling_demand_raises_the_eoq_by_the_square_root_of_two",
         _close(bigger["economic_order_quantity"], base["economic_order_quantity"] * D(2).sqrt()), "the EOQ moves with the square root of demand"),
        ("reorder_point_covers_lead_time_demand",
         base["reorder_point"] >= base["daily_demand"] * D(str(inp["lead_time_days"])), "the reorder point covers the lead-time demand plus safety stock"),
        ("a_higher_service_level_never_lowers_safety_stock",
         base["service_level"] is None or impl({**inp, "service_level": "0.99"})["safety_stock"] >= base["safety_stock"], "a higher service level cannot reduce safety stock"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def inventory_policy_profile(inp):
    try:
        if D(str(inp["annual_demand"])) <= 0:
            return ["annual_demand must be positive"]
        if D(str(inp["order_cost"])) <= 0:
            return ["order_cost must be positive"]
        if D(str(inp["holding_cost_per_unit"])) <= 0:
            return ["holding_cost_per_unit must be positive"]
        if D(str(inp["lead_time_days"])) <= 0:
            return ["lead_time_days must be positive"]
        service = _optional_decimal(inp, "service_level")
        if service is not None and not (0 < service < 1):
            return ["service_level must be greater than zero and below one"]
        sd = _optional_decimal(inp, "daily_demand_sd")
        if sd is not None and sd < 0:
            return ["daily_demand_sd must be non-negative"]
        if sd is not None and service is None:
            return ["service_level is required when a demand standard deviation is declared"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["inventory inputs are malformed: annual_demand, order_cost, holding_cost_per_unit and lead_time_days are required numbers"]

def _inventory_typing(metric):
    if metric == "service_level":
        return ("rate", 4)
    if metric in ("daily_demand_sd", "annual_demand", "economic_order_quantity", "cycle_stock",
                  "safety_stock", "reorder_point", "average_inventory", "daily_demand"):
        return ("units", 2)
    if metric == "orders_per_year":
        return ("units", 2)
    if metric == "safety_factor":
        return ("ratio", 4)
    if metric == "lead_time_days":
        return ("days", 2)
    return ("currency", 2)

def inventory_policy_caveats(out, th):
    return ["Demand is treated as level over the year and the lead time is constant; seasonality, quantity discounts and supplier reliability are not modelled.",
            "Safety stock is the declared service level times the demand standard deviation over the square root of the lead time, using the normal approximation.",
            "The total annual cost counts ordering and holding cost only: no purchase cost, stock-out cost, transport or warehouse space cost."]

def inventory_policy_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    t = ("At an annual demand of " + tok("annual_demand") + ", an order cost of " + tok("order_cost") +
         " and a holding cost of " + tok("holding_cost_per_unit") + " a unit, the economic order quantity is " +
         tok("economic_order_quantity") + ", ordered " + tok("orders_per_year") + " times a year at a total cost of " +
         tok("total_annual_cost") + ".")
    if "safety_stock" in out:
        t += " At the declared service level the safety stock is " + tok("safety_stock") + " and the reorder point is " + tok("reorder_point") + "."
    return t


def queue_analysis_impl(inp):
    arrival = D(str(inp["arrival_rate"]))
    service = D(str(inp["service_rate"]))
    servers = int(D(str(inp.get("servers", "1"))))
    if arrival <= 0:
        raise DataError("arrival_rate must be positive")
    if service <= 0:
        raise DataError("service_rate must be positive")
    if servers < 1 or servers > 50:
        raise DataError("servers must be a whole number from 1 to 50")
    if arrival >= servers * service:
        raise DataError("arrival_rate must be below servers x service_rate, otherwise the queue never clears")
    offered = arrival / service
    rho = offered / servers
    if servers == 1:
        p0 = 1 - rho
        p_wait = rho
        lq = rho * rho / (1 - rho)
    else:
        head = sum((offered ** k) / D(math.factorial(k)) for k in range(servers))
        tail = (offered ** servers) / (D(math.factorial(servers)) * (1 - rho))
        p0 = 1 / (head + tail)
        p_wait = tail * p0
        lq = p_wait * rho / (1 - rho)
    in_service = offered
    l = lq + in_service
    wq = lq / arrival
    w = l / arrival
    return {"arrival_rate": arrival, "service_rate": service, "servers": D(servers),
            "offered_load": offered, "utilisation": rho,
            "average_in_queue": lq, "average_in_system": l,
            "average_wait_in_queue": wq, "average_time_in_system": w,
            "probability_empty": p0, "probability_waiting": p_wait}

def _queue_ref(inp):
    a = float(D(str(inp["arrival_rate"])))
    s = float(D(str(inp["service_rate"])))
    c = int(D(str(inp.get("servers", "1"))))
    offered = a / s
    rho = offered / c
    if c == 1:
        lq = rho * rho / (1 - rho)
    else:
        head = sum(offered ** k / math.factorial(k) for k in range(c))
        tail = offered ** c / (math.factorial(c) * (1 - rho))
        p0 = 1 / (head + tail)
        lq = tail * p0 * rho / (1 - rho)
    return {"utilisation": rho, "average_in_queue": lq, "average_in_system": lq + offered}

def queue_analysis_tests(inp, impl):
    base, ref = impl(inp), _queue_ref(inp)
    arrival = D(str(inp["arrival_rate"]))
    service = D(str(inp["service_rate"]))
    servers = D(str(int(D(str(inp.get("servers", "1"))))))
    probe = {**inp, "servers": "1", "arrival_rate": str(arrival if arrival < service else service / 2)}
    single = impl(probe)
    checks = [
        ("second_implementation_agrees", _close(base["utilisation"], ref["utilisation"], rel=1e-9)
         and _close(base["average_in_queue"], ref["average_in_queue"], rel=1e-9), "float route agrees with the Decimal route"),
        ("utilisation_is_arrival_over_servers_times_service", _close(base["utilisation"], arrival / (servers * service)), "utilisation divides the offered load by the number of servers"),
        ("little_law_holds_in_the_system", _close(base["average_in_system"], arrival * base["average_time_in_system"]), "customers in the system equal arrival rate times time in the system"),
        ("little_law_holds_in_the_queue", _close(base["average_in_queue"], arrival * base["average_wait_in_queue"]), "customers in the queue equal arrival rate times wait in the queue"),
        ("queue_length_is_wait_probability_times_rho_over_one_minus_rho",
         _close(base["average_in_queue"], base["probability_waiting"] * base["utilisation"] / (1 - base["utilisation"])),
         "the queue length follows the Erlang C identity, which reduces to M/M/1 at one server"),
        ("one_server_matches_the_mm1_formula",
         _close(single["average_in_queue"], single["utilisation"] ** 2 / (1 - single["utilisation"])),
         "with one server the result is the M/M/1 queue length"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def queue_analysis_profile(inp):
    try:
        a, s = D(str(inp["arrival_rate"])), D(str(inp["service_rate"]))
        if a <= 0:
            return ["arrival_rate must be positive"]
        if s <= 0:
            return ["service_rate must be positive"]
        c = D(str(inp.get("servers", "1")))
        if c != int(c) or c < 1 or c > 50:
            return ["servers must be a whole number from 1 to 50"]
        if a >= c * s:
            return ["arrival_rate must be below servers x service_rate, otherwise the queue never clears"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["queue inputs are malformed: arrival_rate and service_rate are required numbers"]

def _queue_typing(metric):
    if metric in ("arrival_rate", "service_rate", "servers"):
        return ("count", 4)
    if metric in ("average_wait_in_queue", "average_time_in_system"):
        return ("periods", 4)
    return ("ratio", 4)

def queue_analysis_caveats(out, th):
    return ["The model is a multi-server queue with random arrivals and service times (M/M/c), with constant average rates and interchangeable servers.",
            "Arrivals must be below the number of servers times the service rate; at or above it the queue never clears and the method blocks.",
            "It ignores priorities, abandonment, balking, batch arrivals, server heterogeneity and any distribution other than exponential."]

def queue_analysis_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    return ("At an arrival rate of " + tok("arrival_rate") + " and " + tok("servers") + " servers each serving " +
            tok("service_rate") + ", utilisation is " + tok("utilisation") + ", with " + tok("average_in_queue") +
            " customers waiting on average and a wait of " + tok("average_wait_in_queue") + " periods.")


def capacity_analysis_impl(inp):
    resources = inp["resources"]
    if not resources:
        raise DataError("at least one resource is required")
    caps, labels = [], []
    for i, r in enumerate(resources, 1):
        name = r["name"].strip()
        if not name or len(name) > 60:
            raise DataError("resource %d needs a name of at most 60 characters" % i)
        available = D(str(r["available_hours"]))
        minutes = D(str(r["minutes_per_unit"]))
        if available <= 0:
            raise DataError("resource %d available_hours must be positive" % i)
        if minutes <= 0:
            raise DataError("resource %d minutes_per_unit must be positive" % i)
        caps.append(available * 60 / minutes)
        labels.append(name)
    bottleneck = min(range(len(caps)), key=lambda i: caps[i])
    out = {"max_output": caps[bottleneck], "bottleneck_index": D(bottleneck + 1)}
    for i, c in enumerate(caps, 1):
        out["capacity_%d" % i] = c
    demand = _optional_decimal(inp, "demand")
    if demand is not None:
        if demand < 0:
            raise DataError("demand must be non-negative")
        out["demand"] = demand
        out["capacity_gap"] = out["max_output"] - demand
        for i, c in enumerate(caps, 1):
            out["utilisation_%d" % i] = demand / c
        out["bottleneck_utilisation"] = demand / out["max_output"]
    return out

def _capacity_ref(inp):
    caps = [float(D(str(r["available_hours"]))) * 60 / float(D(str(r["minutes_per_unit"]))) for r in inp["resources"]]
    return {"max_output": min(caps)}

def capacity_analysis_tests(inp, impl):
    base, ref = impl(inp), _capacity_ref(inp)
    caps = [base["capacity_%d" % i] for i in range(1, len(inp["resources"]) + 1)]
    demand = base.get("demand")
    checks = [
        ("second_implementation_agrees", _close(base["max_output"], ref["max_output"], rel=1e-9), "float route agrees with the Decimal route"),
        ("capacity_is_available_minutes_over_minutes_per_unit",
         all(_close(base["capacity_%d" % (i + 1)], D(str(r["available_hours"])) * 60 / D(str(r["minutes_per_unit"])))
             for i, r in enumerate(inp["resources"])), "each capacity is available hours times sixty over minutes per unit"),
        ("bottleneck_is_the_smallest_capacity", _close(base["max_output"], min(caps)), "throughput is set by the smallest capacity"),
        ("utilisation_is_demand_over_capacity",
         demand is None or all(_close(base["utilisation_%d" % (i + 1)], demand / base["capacity_%d" % (i + 1)]) for i in range(len(caps))),
         "utilisation at the declared demand is demand over capacity"),
        ("the_reported_bottleneck_index_points_at_the_smallest_capacity",
         _close(caps[int(base["bottleneck_index"]) - 1], base["max_output"]), "the bottleneck index identifies the smallest capacity"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def capacity_analysis_profile(inp):
    try:
        resources = inp.get("resources")
        if not isinstance(resources, list) or not resources:
            return ["at least one resource is required"]
        if len(resources) > 20:
            return ["at most twenty resources are supported"]
        for i, r in enumerate(resources, 1):
            if not isinstance(r, dict) or not isinstance(r.get("name"), str) or not r["name"].strip():
                return ["resource %d needs a name" % i]
            if D(str(r["available_hours"])) <= 0:
                return ["resource %d available_hours must be positive" % i]
            if D(str(r["minutes_per_unit"])) <= 0:
                return ["resource %d minutes_per_unit must be positive" % i]
        demand = _optional_decimal(inp, "demand")
        if demand is not None and demand < 0:
            return ["demand must be non-negative"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["capacity inputs are malformed: resources must be records with a name, available_hours and minutes_per_unit"]

def _capacity_typing(metric):
    if metric.startswith("utilisation_") or metric == "bottleneck_utilisation":
        return ("ratio", 4)
    if metric == "bottleneck_index":
        return ("count", 0)
    return ("units", 2)

def capacity_analysis_caveats(out, th):
    return ["Capacity is available hours times sixty over minutes per unit, with no allowance for breaks, maintenance, scrap or changeover.",
            "The bottleneck is the resource with the smallest capacity; the method does not schedule work, buffer or batch it.",
            "Demand is a flat figure for the same period as the available hours; a changing mix or routing needs its own run per product."]

def capacity_analysis_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    t = ("The process capacity is " + tok("max_output") + " units, set by the bottleneck resource at position " +
         tok("bottleneck_index") + ".")
    if "demand" in out:
        t += (" At the declared demand of " + tok("demand") + ", the bottleneck runs at " + tok("bottleneck_utilisation") +
              " and the capacity gap is " + tok("capacity_gap") + ".")
    return t


# ---------- Scheduling, quality, costing and sales variance (B-116) ----------

def _act_id(value):
    text = str(value or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_\-]{1,20}", text):
        raise DataError("each activity id must be 1-20 letters, digits, - or _")
    return text

def cpm_schedule_impl(inp):
    acts = inp["activities"]
    three = str(inp.get("estimate", "single")) == "three_point"
    if not acts:
        raise DataError("at least one activity is required")
    if len(acts) > 200:
        raise DataError("at most 200 activities are supported")
    nodes, order_in = {}, []
    for a in acts:
        aid = _act_id(a.get("id"))
        if aid in nodes:
            raise DataError("duplicate activity id " + aid)
        preds = [p.strip() for p in str(a.get("predecessors") or "").split(",") if p.strip()]
        if three:
            o, m, p = (D(str(a[k])) for k in ("optimistic", "most_likely", "pessimistic"))
            if o < 0 or not (o <= m <= p):
                raise DataError("activity " + aid + " needs 0 <= optimistic <= most_likely <= pessimistic")
            dur, var = (o + 4 * m + p) / 6, ((p - o) / 6) ** 2
        else:
            dur = D(str(a["duration"]))
            if dur < 0:
                raise DataError("activity " + aid + " duration must be non-negative")
            var = D(0)
        nodes[aid] = {"dur": dur, "var": var, "preds": preds}
        order_in.append(aid)
    for aid, node in nodes.items():
        for p in node["preds"]:
            if p not in nodes:
                raise DataError("activity " + aid + " cites unknown predecessor " + p)
            if p == aid:
                raise DataError("activity " + aid + " cannot be its own predecessor")
    indeg = {aid: len(n["preds"]) for aid, n in nodes.items()}
    succ = {aid: [] for aid in nodes}
    for aid, n in nodes.items():
        for p in n["preds"]:
            succ[p].append(aid)
    queue = [aid for aid in order_in if indeg[aid] == 0]
    topo = []
    while queue:
        aid = queue.pop(0)
        topo.append(aid)
        for s in succ[aid]:
            indeg[s] -= 1
            if indeg[s] == 0:
                queue.append(s)
    if len(topo) != len(nodes):
        raise DataError("the predecessor graph contains a cycle")
    es, ef = {}, {}
    for aid in topo:
        es[aid] = max((ef[p] for p in nodes[aid]["preds"]), default=D(0))
        ef[aid] = es[aid] + nodes[aid]["dur"]
    duration = max(ef.values())
    ls, lf = {}, {}
    for aid in reversed(topo):
        lf[aid] = min((ls[s] for s in succ[aid]), default=duration)
        ls[aid] = lf[aid] - nodes[aid]["dur"]
    out = {"project_duration": duration, "activity_count": D(len(nodes))}
    critical = [aid for aid in order_in if ls[aid] - es[aid] == 0]
    for aid in order_in:
        out["es_" + aid] = es[aid]
        out["ef_" + aid] = ef[aid]
        out["ls_" + aid] = ls[aid]
        out["lf_" + aid] = lf[aid]
        out["float_" + aid] = ls[aid] - es[aid]
        out["critical_" + aid] = D(1 if aid in critical else 0)
    out["critical_count"] = D(len(critical))
    if three:
        out["pert_variance"] = sum((nodes[aid]["var"] for aid in critical), D(0))
        out["pert_stdev"] = out["pert_variance"].sqrt()
    return out

def _cpm_ref(inp):
    nodes = {}
    for a in inp["activities"]:
        aid = str(a["id"]).strip()
        if str(inp.get("estimate", "single")) == "three_point":
            o, m, p = (float(D(str(a[k]))) for k in ("optimistic", "most_likely", "pessimistic"))
            d = (o + 4 * m + p) / 6
        else:
            d = float(D(str(a["duration"])))
        nodes[aid] = (d, [x.strip() for x in str(a.get("predecessors") or "").split(",") if x.strip()])
    ef = {}
    pending = dict(nodes)
    while pending:
        progressed = False
        for aid in list(pending):
            d, preds = pending[aid]
            if all(p in ef for p in preds):
                ef[aid] = max((ef[p] for p in preds), default=0.0) + d
                del pending[aid]
                progressed = True
        if not progressed:
            raise ValueError("cycle")
    return {"project_duration": max(ef.values())}

def cpm_schedule_tests(inp, impl):
    base, ref = impl(inp), _cpm_ref(inp)
    ids = [str(a["id"]).strip() for a in inp["activities"]]
    node = {str(a["id"]).strip(): a for a in inp["activities"]}
    preds = {i: [p.strip() for p in str(node[i].get("predecessors") or "").split(",") if p.strip()] for i in ids}
    succ = {i: [x for x in ids if i in preds[x]] for i in ids}
    checks = [
        ("second_implementation_agrees", _close(base["project_duration"], ref["project_duration"], rel=1e-9), "float route agrees with the Decimal route"),
        ("early_start_is_the_latest_predecessor_finish",
         all(base["es_" + i] == max((base["ef_" + p] for p in preds[i]), default=D(0)) for i in ids), "each activity starts when its last predecessor finishes"),
        ("late_finish_is_the_earliest_successor_start",
         all(base["lf_" + i] == min((base["ls_" + s] for s in succ[i]), default=base["project_duration"]) for i in ids), "each activity finishes no later than its first successor must start"),
        ("critical_activities_have_zero_float",
         all((base["critical_" + i] == 1) == (base["float_" + i] == 0) for i in ids), "the critical flag is exactly the zero-float activities"),
        ("project_duration_is_the_latest_early_finish",
         base["project_duration"] == max(base["ef_" + i] for i in ids), "the project ends when the last activity ends"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def cpm_schedule_profile(inp):
    try:
        acts = inp.get("activities")
        if not isinstance(acts, list) or not acts:
            return ["at least one activity is required"]
        ids = set()
        for i, a in enumerate(acts, 1):
            if not isinstance(a, dict):
                return ["activity %d must be an object" % i]
            aid = str(a.get("id") or "").strip()
            if not re.fullmatch(r"[A-Za-z0-9_\-]{1,20}", aid):
                return ["activity %d needs an id of 1-20 letters, digits, - or _" % i]
            if aid in ids:
                return ["duplicate activity id " + aid]
            ids.add(aid)
            if str(inp.get("estimate", "single")) == "three_point":
                try:
                    o, m, p = (D(str(a[k])) for k in ("optimistic", "most_likely", "pessimistic"))
                except (InvalidOperation, ValueError, TypeError, KeyError):
                    return ["activity " + aid + " needs optimistic, most_likely and pessimistic numbers"]
                if o < 0 or not (o <= m <= p):
                    return ["activity " + aid + " needs 0 <= optimistic <= most_likely <= pessimistic"]
            else:
                if "duration" not in a:
                    return ["activity " + aid + " needs a duration"]
                if D(str(a["duration"])) < 0:
                    return ["activity " + aid + " duration must be non-negative"]
        for a in acts:
            for p in str(a.get("predecessors") or "").split(","):
                p = p.strip()
                if p and p not in ids:
                    return ["activity %s cites unknown predecessor %s" % (str(a["id"]).strip(), p)]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["schedule inputs are malformed: activities must carry an id and a duration or the three estimates"]

def _cpm_typing(metric):
    if metric == "activity_count" or metric == "critical_count" or metric.startswith("critical_"):
        return ("count", 0)
    if metric in ("pert_variance", "pert_stdev"):
        return ("ratio", 4)
    return ("periods", 2)

def cpm_schedule_caveats(out, th):
    return ["Durations are deterministic (or the expected value of the three-point estimate); the schedule does not model resource limits, calendars or uncertainty beyond the PERT variance.",
            "The critical path is where float is zero; a delay there delays the project, but a critical path is not automatically the riskiest.",
            "PERT uses (optimistic + 4 x most likely + pessimistic) / 6 and sums the variances on the critical path; those are declared conventions."]

def cpm_schedule_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    t = ("The project finishes in " + tok("project_duration") + " periods, with " + tok("critical_count") +
         " of " + tok("activity_count") + " activities on the critical path.")
    if "pert_variance" in out:
        t += " The PERT variance along that path is " + tok("pert_variance") + "."
    return t


def _cpm_network(activities, durations=None):
    """A small acyclic CPM core shared by levelling and crashing."""
    nodes, order = {}, []
    for a in activities:
        aid = _act_id(a.get("id"))
        if aid in nodes:
            raise DataError("duplicate activity id " + aid)
        dur = D(str(a["duration"])) if durations is None else D(str(durations[aid]))
        if dur < 0:
            raise DataError("activity " + aid + " duration must be non-negative")
        preds = [p.strip() for p in str(a.get("predecessors") or "").split(",") if p.strip()]
        nodes[aid] = {"dur": dur, "preds": preds}
        order.append(aid)
    for aid, node in nodes.items():
        for p in node["preds"]:
            if p not in nodes:
                raise DataError("activity " + aid + " cites unknown predecessor " + p)
            if p == aid:
                raise DataError("activity " + aid + " cannot be its own predecessor")
    succ = {aid: [] for aid in nodes}
    indeg = {aid: len(n["preds"]) for aid, n in nodes.items()}
    for aid, n in nodes.items():
        for p in n["preds"]:
            succ[p].append(aid)
    queue = [aid for aid in order if indeg[aid] == 0]
    topo = []
    while queue:
        aid = queue.pop(0)
        topo.append(aid)
        for s in succ[aid]:
            indeg[s] -= 1
            if indeg[s] == 0:
                queue.append(s)
    if len(topo) != len(nodes):
        raise DataError("the predecessor graph contains a cycle")
    es, ef = {}, {}
    for aid in topo:
        es[aid] = max((ef[p] for p in nodes[aid]["preds"]), default=D(0))
        ef[aid] = es[aid] + nodes[aid]["dur"]
    duration = max(ef.values())
    ls, lf = {}, {}
    for aid in reversed(topo):
        lf[aid] = min((ls[s] for s in succ[aid]), default=duration)
        ls[aid] = lf[aid] - nodes[aid]["dur"]
    return {"order": order, "nodes": nodes, "topo": topo, "succ": succ,
            "es": es, "ef": ef, "ls": ls, "lf": lf, "duration": duration}


def _whole(value, what):
    number = D(str(value))
    if number != number.to_integral_value():
        raise DataError(what + " must be a whole number of periods")
    return int(number)


def _fits(schedule, demand, capacity, start, duration, extra=0):
    for period in range(start, start + duration):
        used = sum(demand[aid] for aid, (other_start, other_duration) in schedule.items()
                   if other_start <= period < other_start + other_duration)
        if used + extra > capacity:
            return False
    return True


def _load_by_period(schedule, demand, capacity):
    """Peak and over-capacity periods for one resource."""
    peak, over = 0, 0
    for period in range(0, max([s + d for s, d in schedule.values()] or [0])):
        load = sum(demand[aid] for aid, (start, dur) in schedule.items() if start <= period < start + dur)
        peak = max(peak, load)
        if load > capacity:
            over += 1
    return peak, over


def resource_leveling_impl(inp):
    activities, resources = inp["activities"], inp["resources"]
    capacity = {}
    for r in resources:
        name = _act_id(r.get("name"))
        cap = _whole(r.get("capacity"), "resource " + name + " capacity")
        if cap <= 0:
            raise DataError("resource " + name + " capacity must be positive")
        capacity[name] = cap
    net = _cpm_network(activities)
    demand, resource = {}, {}
    for a in activities:
        aid = _act_id(a.get("id"))
        res = _act_id(a.get("resource"))
        if res not in capacity:
            raise DataError("activity " + aid + " cites unknown resource " + res)
        amount = _whole(a.get("demand"), "activity " + aid + " demand")
        if amount < 0 or amount > capacity[res]:
            raise DataError("activity %s demand must be between 0 and the capacity of %s" % (aid, res))
        demand[aid], resource[aid] = amount, res
        net["nodes"][aid]["dur_int"] = _whole(net["nodes"][aid]["dur"], "activity " + aid + " duration")
    before_schedule = {aid: (int(net["es"][aid]), net["nodes"][aid]["dur_int"]) for aid in net["order"]}
    peak_before, over_before = 0, 0
    for name, cap in capacity.items():
        schedule = {aid: v for aid, v in before_schedule.items() if resource[aid] == name}
        peak, over = _load_by_period(schedule, {aid: demand[aid] for aid in schedule}, cap)
        peak_before, over_before = max(peak_before, peak), over_before + over
    sequence = sorted(net["order"], key=lambda aid: (net["es"][aid], -net["nodes"][aid]["dur"], aid))
    starts = {}
    for aid in sequence:
        earliest = max((starts[p] + net["nodes"][p]["dur_int"] for p in net["nodes"][aid]["preds"]), default=0)
        earliest = max(earliest, int(net["es"][aid]))
        start = earliest
        while True:
            peers = {x: (s, net["nodes"][x]["dur_int"]) for x, s in starts.items()
                     if resource[x] == resource[aid]}
            if _fits(peers, {x: demand[x] for x in peers}, capacity[resource[aid]],
                     start, net["nodes"][aid]["dur_int"], extra=demand[aid]):
                break
            start += 1
        starts[aid] = start
    after_schedule = {aid: (starts[aid], net["nodes"][aid]["dur_int"]) for aid in net["order"]}
    peak_after, over_after = 0, 0
    for name, cap in capacity.items():
        schedule = {aid: v for aid, v in after_schedule.items() if resource[aid] == name}
        peak, over = _load_by_period(schedule, {aid: demand[aid] for aid in schedule}, cap)
        peak_after, over_after = max(peak_after, peak), over_after + over
    levelled = max(starts[aid] + net["nodes"][aid]["dur_int"] for aid in net["order"])
    out = {"cpm_duration": net["duration"], "levelled_duration": D(levelled),
           "levelling_delay": D(levelled) - net["duration"], "activity_count": D(len(net["order"])),
           "overallocated_periods_before": D(over_before), "overallocated_periods_after": D(over_after),
           "peak_demand_before": D(peak_before), "peak_demand_after": D(peak_after)}
    for aid in net["order"]:
        out["lv_start_" + aid] = D(starts[aid])
        out["lv_finish_" + aid] = D(starts[aid] + net["nodes"][aid]["dur_int"])
        out["lv_delay_" + aid] = D(starts[aid]) - net["es"][aid]
    return out


def _level_float(inp):
    activities = inp["activities"]
    capacity = {str(r["name"]).strip(): int(float(D(str(r["capacity"])))) for r in inp["resources"]}
    nodes = {}
    for a in activities:
        aid = str(a["id"]).strip()
        nodes[aid] = {"dur": int(float(D(str(a["duration"])))),
                      "preds": [p.strip() for p in str(a.get("predecessors") or "").split(",") if p.strip()],
                      "res": str(a["resource"]).strip(), "dem": int(float(D(str(a["demand"]))))}
    ef = {}
    pending = dict(nodes)
    while pending:
        progressed = False
        for aid in list(pending):
            if all(p in ef for p in pending[aid]["preds"]):
                ef[aid] = max((ef[p] for p in pending[aid]["preds"]), default=0) + pending[aid]["dur"]
                del pending[aid]
                progressed = True
        if not progressed:
            raise ValueError("cycle")
    es = {aid: ef[aid] - nodes[aid]["dur"] for aid in nodes}
    sequence = sorted(nodes, key=lambda aid: (es[aid], -nodes[aid]["dur"], aid))
    starts = {}
    for aid in sequence:
        start = max([starts[p] + nodes[p]["dur"] for p in nodes[aid]["preds"]] + [es[aid]])
        peers = {x: (s, nodes[x]["dur"]) for x, s in starts.items() if nodes[x]["res"] == nodes[aid]["res"]}
        while not _fits(peers, {x: nodes[x]["dem"] for x in peers}, capacity[nodes[aid]["res"]],
                        start, nodes[aid]["dur"], extra=nodes[aid]["dem"]):
            start += 1
        starts[aid] = start
    return {"levelled_duration": float(max(starts[a] + nodes[a]["dur"] for a in nodes)), "starts": starts}


def resource_leveling_tests(inp, impl):
    base, ref = impl(inp), _level_float(inp)
    net = _cpm_network(inp["activities"])
    capacity = {str(r["name"]).strip(): int(float(D(str(r["capacity"])))) for r in inp["resources"]}
    resource = {str(a["id"]).strip(): str(a["resource"]).strip() for a in inp["activities"]}
    demand = {str(a["id"]).strip(): int(float(D(str(a["demand"])))) for a in inp["activities"]}
    starts = {aid: int(base["lv_start_" + aid]) for aid in net["order"]}
    duration = {aid: _whole(net["nodes"][aid]["dur"], "activity " + aid + " duration") for aid in net["order"]}
    schedule = {aid: (starts[aid], duration[aid]) for aid in net["order"]}
    peak_ok = True
    for name, cap in capacity.items():
        used = {aid: v for aid, v in schedule.items() if resource[aid] == name}
        peak, over = _load_by_period(used, {aid: demand[aid] for aid in used}, cap)
        peak_ok = peak_ok and over == 0 and peak <= cap
    checks = [
        ("second_implementation_agrees", _close(base["levelled_duration"], ref["levelled_duration"], rel=1e-9)
         and all(_close(base["lv_start_" + a], ref["starts"][a], rel=1e-9) for a in net["order"]),
         "float route agrees with the Decimal route"),
        ("no_period_exceeds_a_resource_capacity", peak_ok, "every levelled period is within capacity"),
        ("precedence_is_respected", all(starts[a] >= starts[p] + duration[p]
                                        for a in net["order"] for p in net["nodes"][a]["preds"]),
         "no activity starts before its predecessor finishes"),
        ("no_activity_starts_before_its_cpm_early_start",
         all(starts[a] >= net["es"][a] for a in net["order"]), "levelling only delays work"),
        ("levelling_never_shortens_the_project",
         base["levelled_duration"] >= base["cpm_duration"], "the resource-constrained plan is at least as long"),
    ]
    return [(name, ok) for name, ok, _ in checks]


def resource_leveling_profile(inp):
    try:
        acts, resources = inp.get("activities"), inp.get("resources")
        if not isinstance(acts, list) or not acts:
            return ["at least one activity is required"]
        if not isinstance(resources, list) or not resources:
            return ["at least one resource is required"]
        names = set()
        for i, r in enumerate(resources, 1):
            if not isinstance(r, dict):
                return ["resource %d must be an object" % i]
            name = str(r.get("name") or "").strip()
            if not re.fullmatch(r"[A-Za-z0-9_\-]{1,20}", name):
                return ["resource %d needs a name of 1-20 letters, digits, - or _" % i]
            if name in names:
                return ["duplicate resource name " + name]
            names.add(name)
            if D(str(r.get("capacity", ""))) <= 0:
                return ["resource " + name + " capacity must be positive"]
        seen = set()
        for i, a in enumerate(acts, 1):
            if not isinstance(a, dict):
                return ["activity %d must be an object" % i]
            aid = str(a.get("id") or "").strip()
            if not re.fullmatch(r"[A-Za-z0-9_\-]{1,20}", aid) or aid in seen:
                return ["activity %d needs a unique id of 1-20 letters, digits, - or _" % i]
            seen.add(aid)
            if "duration" not in a or D(str(a["duration"])) < 0:
                return ["activity " + aid + " needs a non-negative duration"]
            if str(a["resource"]).strip() not in names:
                return ["activity " + aid + " cites an unknown resource"]
            amount, cap = D(str(a.get("demand", ""))), D(str(next(r for r in resources if str(r["name"]).strip() == str(a["resource"]).strip())["capacity"]))
            if amount < 0 or amount > cap:
                return ["activity %s demand must be between 0 and its resource capacity" % aid]
        for a in acts:
            for p in str(a.get("predecessors") or "").split(","):
                if p.strip() and p.strip() not in seen:
                    return ["activity %s cites unknown predecessor %s" % (str(a["id"]).strip(), p.strip())]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError, StopIteration):
        return ["resource-levelling inputs are malformed; every activity needs id, duration, resource and demand"]


def _level_typing(metric):
    if metric in ("overallocated_periods_before", "overallocated_periods_after", "peak_demand_before",
                  "peak_demand_after", "activity_count"):
        return ("count", 0)
    return ("periods", 2)


def resource_leveling_caveats(out, th):
    return ["Levelling is serial and non-preemptive: activities keep their duration and are delayed until their declared resource has capacity.",
            "The order is by early start, then longest duration, then activity id; a different priority rule can produce a different, equally valid plan.",
            "Only one resource per activity and whole-period durations and demands are supported; calendars, multiple resources per activity and preemption are not."]


def resource_leveling_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    return ("The resource-constrained plan finishes in " + tok("levelled_duration") + " periods, against " +
            tok("cpm_duration") + " without resource limits, a delay of " + tok("levelling_delay") +
            " periods. " + tok("overallocated_periods_before") + " periods were over capacity before levelling and " +
            tok("overallocated_periods_after") + " after.")


def project_crashing_impl(inp):
    activities = inp["activities"]
    normal, lowest, cost = {}, {}, {}
    for a in activities:
        aid = _act_id(a.get("id"))
        n = _whole(a.get("normal_duration"), "activity " + aid + " normal_duration")
        c = _whole(a.get("crash_duration"), "activity " + aid + " crash_duration")
        if c < 0 or c > n:
            raise DataError("activity " + aid + " needs 0 <= crash_duration <= normal_duration")
        amount = D(str(a.get("crash_cost", "0")))
        if amount < 0:
            raise DataError("activity " + aid + " crash_cost must be non-negative")
        if n > c and amount == 0:
            raise DataError("activity " + aid + " can be crashed but has no crash cost")
        normal[aid], lowest[aid], cost[aid] = n, c, amount
    net = _cpm_network(activities, durations=normal)
    target = _whole(inp.get("target_duration"), "target_duration")
    if target < 0:
        raise DataError("target_duration must be non-negative")
    feasible = _cpm_network(activities, durations=lowest)["duration"]
    if target < feasible:
        raise DataError("target_duration is below the fully crashed duration of " + str(feasible))
    normal_duration = net["duration"]
    current = dict(normal)
    spend, crashed = D(0), {aid: 0 for aid in normal}
    guard = 0
    while True:
        net = _cpm_network(activities, durations=current)
        if net["duration"] <= target:
            break
        guard += 1
        if guard > 10000:
            raise DataError("crashing did not converge")
        critical = [aid for aid in net["order"] if net["ls"][aid] - net["es"][aid] == 0 and current[aid] > lowest[aid]]
        if not critical:
            raise DataError("target_duration cannot be reached by crashing the critical path")
        def rate(aid):
            return (cost[aid] / D(normal[aid] - lowest[aid]), aid)
        chosen = min(critical, key=rate)
        current[chosen] -= 1
        crashed[chosen] += 1
        spend += cost[chosen] / D(normal[chosen] - lowest[chosen])
    out = {"normal_duration": normal_duration,
           "crashed_duration": _cpm_network(activities, durations=current)["duration"],
           "target_duration": D(target), "total_crash_cost": spend, "activity_count": D(len(normal))}
    for aid in net["order"]:
        out["crash_periods_" + aid] = D(crashed[aid])
        out["crash_cost_" + aid] = D(crashed[aid]) * (cost[aid] / D(normal[aid] - lowest[aid])) if normal[aid] > lowest[aid] else D(0)
        out["final_duration_" + aid] = D(current[aid])
    return out


def _crash_float(inp):
    normal = {str(a["id"]).strip(): int(float(D(str(a["normal_duration"])))) for a in inp["activities"]}
    lowest = {str(a["id"]).strip(): int(float(D(str(a["crash_duration"])))) for a in inp["activities"]}
    cost = {str(a["id"]).strip(): float(D(str(a.get("crash_cost", "0")))) for a in inp["activities"]}
    preds = {str(a["id"]).strip(): [p.strip() for p in str(a.get("predecessors") or "").split(",") if p.strip()]
             for a in inp["activities"]}
    target = int(float(D(str(inp["target_duration"]))))
    current = dict(normal)

    def network(durs):
        ef, pending, order = {}, dict(durs), []
        while pending:
            moved = False
            for aid in list(pending):
                if all(p in ef for p in preds[aid]):
                    ef[aid] = max((ef[p] for p in preds[aid]), default=0) + durs[aid]
                    del pending[aid]
                    order.append(aid)
                    moved = True
            if not moved:
                raise ValueError("cycle")
        duration = max(ef.values())
        succ = {aid: [x for x in durs if aid in preds[x]] for aid in durs}
        ls, lf = {}, {}
        for aid in reversed(order):
            lf[aid] = min((ls[s] for s in succ[aid]), default=duration)
            ls[aid] = lf[aid] - durs[aid]
        es = {aid: ef[aid] - durs[aid] for aid in durs}
        return duration, [aid for aid in durs if ls[aid] - es[aid] == 0]

    spend = 0.0
    while network(current)[0] > target:
        duration, critical = network(current)
        candidates = [aid for aid in critical if current[aid] > lowest[aid]]
        if not candidates:
            raise ValueError("unreachable")
        aid = min(candidates, key=lambda x: (cost[x] / (normal[x] - lowest[x]), x))
        current[aid] -= 1
        spend += cost[aid] / (normal[aid] - lowest[aid])
    return {"crashed_duration": network(current)[0], "total_crash_cost": spend, "final": current}


def project_crashing_tests(inp, impl):
    base, ref = impl(inp), _crash_float(inp)
    normal = {str(a["id"]).strip(): int(float(D(str(a["normal_duration"])))) for a in inp["activities"]}
    lowest = {str(a["id"]).strip(): int(float(D(str(a["crash_duration"])))) for a in inp["activities"]}
    cost = {str(a["id"]).strip(): D(str(a.get("crash_cost", "0"))) for a in inp["activities"]}
    final = {aid: int(base["final_duration_" + aid]) for aid in normal}
    recomputed = _cpm_network(inp["activities"], durations=final)["duration"]
    spend = sum(base["crash_cost_" + aid] for aid in normal)
    checks = [
        ("second_implementation_agrees", _close(base["crashed_duration"], ref["crashed_duration"], rel=1e-9)
         and _close(base["total_crash_cost"], ref["total_crash_cost"], rel=1e-9),
         "float route agrees with the Decimal route"),
        ("target_duration_is_met", base["crashed_duration"] <= base["target_duration"],
         "the crashed plan is no longer than the target"),
        ("every_activity_stays_within_its_crash_limits",
         all(lowest[a] <= final[a] <= normal[a] for a in normal), "no activity is crashed beyond its declared range"),
        ("total_cost_is_the_sum_of_the_activity_costs", _close(base["total_crash_cost"], spend, rel=1e-9),
         "the reported cost is the sum of the crash costs"),
        ("recomputed_network_matches_the_crashed_duration", D(recomputed) == base["crashed_duration"],
         "the dates recompute to the same project duration"),
    ]
    return [(name, ok) for name, ok, _ in checks]


def project_crashing_profile(inp):
    try:
        acts = inp.get("activities")
        if not isinstance(acts, list) or not acts:
            return ["at least one activity is required"]
        for i, a in enumerate(acts, 1):
            if not isinstance(a, dict):
                return ["activity %d must be an object" % i]
            aid = str(a.get("id") or "").strip()
            if not re.fullmatch(r"[A-Za-z0-9_\-]{1,20}", aid):
                return ["activity %d needs an id of 1-20 letters, digits, - or _" % i]
            n, c = D(str(a.get("normal_duration", ""))), D(str(a.get("crash_duration", "")))
            if c < 0 or c > n:
                return ["activity " + aid + " needs 0 <= crash_duration <= normal_duration"]
            if D(str(a.get("crash_cost", "0"))) < 0:
                return ["activity " + aid + " crash_cost must be non-negative"]
        if "target_duration" not in inp or D(str(inp["target_duration"])) < 0:
            return ["target_duration must be a non-negative number"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["crashing inputs are malformed; every activity needs normal_duration, crash_duration and crash_cost"]


def _crash_typing(metric):
    if metric in ("activity_count",) or metric.startswith("crash_periods_"):
        return ("count", 0)
    if metric.startswith("crash_cost_") or metric == "total_crash_cost":
        return ("currency", 2)
    return ("periods", 2)


def project_crashing_caveats(out, th):
    return ["Crashing is a greedy rule: one period at a time, the cheapest critical activity, recomputing the network after each step. It is not a linear-programming optimum.",
            "Crash cost is treated as linear between the normal and crash durations; shared or non-linear costs are not modelled.",
            "A target below the fully crashed duration or beyond the normal duration is refused or reported unchanged."]


def project_crashing_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    return ("The normal plan lasts " + tok("normal_duration") + " periods. Crashing it to the target of " +
            tok("target_duration") + " costs " + tok("total_crash_cost") + " and leaves a duration of " +
            tok("crashed_duration") + ".")


def _calendar_numbers(text):
    raw = [p.strip() for p in str(text or "").split(",") if p.strip()]
    values = []
    for item in raw:
        value = _whole(item, "working period")
        if value < 0:
            raise DataError("working periods must be non-negative")
        values.append(value)
    if not values:
        raise DataError("at least one working period is required")
    return sorted(set(values))


def _calendar_advance(work, start, duration):
    index = next((i for i, value in enumerate(work) if value >= start), None)
    if index is None:
        raise DataError("the calendar has no working period at or after the required start")
    if duration == 0:
        return work[index], work[index], []
    if index + duration > len(work):
        raise DataError("the calendar is too short for the declared durations")
    occupied = work[index:index + duration]
    return occupied[0], occupied[-1] + 1, occupied


def _calendar_latest(work, finish, duration):
    if duration == 0:
        eligible = [value for value in work if value <= finish]
        if not eligible:
            raise DataError("the calendar cannot place a milestone before its late finish")
        return eligible[-1]
    for index in range(len(work) - duration, -1, -1):
        block = work[index:index + duration]
        if block and block[-1] + 1 <= finish:
            return block[0]
    raise DataError("the calendar cannot place an activity before its late finish")


def calendar_schedule_impl(inp):
    work = _calendar_numbers(inp.get("working_periods"))
    activities = inp["activities"]
    nodes, order = {}, []
    for a in activities:
        aid = _act_id(a.get("id"))
        if aid in nodes:
            raise DataError("duplicate activity id " + aid)
        dur = _whole(a.get("duration"), "activity " + aid + " duration")
        preds = [p.strip() for p in str(a.get("predecessors") or "").split(",") if p.strip()]
        nodes[aid] = {"dur": dur, "preds": preds}
        order.append(aid)
    for aid, node in nodes.items():
        for p in node["preds"]:
            if p not in nodes:
                raise DataError("activity " + aid + " cites unknown predecessor " + p)
            if p == aid:
                raise DataError("activity " + aid + " cannot be its own predecessor")
    succ = {aid: [] for aid in nodes}
    indeg = {aid: len(n["preds"]) for aid, n in nodes.items()}
    for aid, n in nodes.items():
        for p in n["preds"]:
            succ[p].append(aid)
    queue = [aid for aid in order if indeg[aid] == 0]
    topo = []
    while queue:
        aid = queue.pop(0)
        topo.append(aid)
        for s in succ[aid]:
            indeg[s] -= 1
            if indeg[s] == 0:
                queue.append(s)
    if len(topo) != len(nodes):
        raise DataError("the predecessor graph contains a cycle")
    es, ef = {}, {}
    for aid in topo:
        earliest = max((ef[p] for p in nodes[aid]["preds"]), default=0)
        start, finish, _ = _calendar_advance(work, earliest, nodes[aid]["dur"])
        es[aid], ef[aid] = start, finish
    duration = max(ef.values())
    ls, lf = {}, {}
    for aid in reversed(topo):
        latest = min((ls[s] for s in succ[aid]), default=duration)
        lf[aid] = latest
        ls[aid] = _calendar_latest(work, latest, nodes[aid]["dur"])
    critical = [aid for aid in order if ls[aid] - es[aid] == 0]
    out = {"project_duration": D(duration), "activity_count": D(len(nodes)),
           "working_periods": D(len(work)), "critical_count": D(len(critical))}
    for aid in order:
        out["es_" + aid] = D(es[aid])
        out["ef_" + aid] = D(ef[aid])
        out["ls_" + aid] = D(ls[aid])
        out["lf_" + aid] = D(lf[aid])
        out["float_" + aid] = D(ls[aid] - es[aid])
        out["critical_" + aid] = D(1 if aid in critical else 0)
    return out


def _calendar_float(inp):
    work = sorted({int(float(D(str(x)))) for x in str(inp.get("working_periods") or "").split(",") if x.strip()})
    nodes = {}
    for a in inp["activities"]:
        aid = str(a["id"]).strip()
        nodes[aid] = (int(float(D(str(a["duration"])))),
                      [p.strip() for p in str(a.get("predecessors") or "").split(",") if p.strip()])
    ef, pending = {}, dict(nodes)
    while pending:
        moved = False
        for aid in list(pending):
            dur, preds = pending[aid]
            if all(p in ef for p in preds):
                earliest = max((ef[p] for p in preds), default=0)
                index = next(i for i, value in enumerate(work) if value >= earliest)
                ef[aid] = work[index + dur - 1] + 1
                del pending[aid]
                moved = True
        if not moved:
            raise ValueError("cycle")
    return {"project_duration": max(ef.values())}


def calendar_schedule_tests(inp, impl):
    base, ref = impl(inp), _calendar_float(inp)
    work = _calendar_numbers(inp.get("working_periods"))
    ids = [str(a["id"]).strip() for a in inp["activities"]]
    nodes = {str(a["id"]).strip(): a for a in inp["activities"]}
    preds = {i: [p.strip() for p in str(nodes[i].get("predecessors") or "").split(",") if p.strip()] for i in ids}
    before = _cpm_network([{**a, "duration": a["duration"]} for a in inp["activities"]])["duration"]
    checks = [
        ("second_implementation_agrees", _close(base["project_duration"], ref["project_duration"], rel=1e-9),
         "float route agrees with the Decimal route"),
        ("precedence_is_respected", all(base["es_" + a] >= base["ef_" + p] for a in ids for p in preds[a]),
         "no activity starts before its predecessor finishes"),
        ("every_working_period_is_used", all(
            sum(1 for p in work if int(base["es_" + aid]) <= p < int(base["ef_" + aid])) == int(D(str(nodes[aid]["duration"])))
            for aid in ids), "each activity occupies exactly its declared number of working periods"),
        ("critical_activities_have_zero_float",
         all((base["critical_" + i] == 1) == (base["float_" + i] == 0) for i in ids),
         "the critical flag is exactly the zero-float activities"),
        ("the_calendar_cannot_shorten_the_work",
         base["project_duration"] >= before, "skipping non-working periods cannot make the project shorter"),
    ]
    return [(name, ok) for name, ok, _ in checks]


def calendar_schedule_profile(inp):
    try:
        work = [p.strip() for p in str(inp.get("working_periods") or "").split(",") if p.strip()]
        if not work:
            return ["working_periods must list at least one period"]
        values = []
        for item in work:
            value = D(str(item))
            if value < 0 or value != value.to_integral_value():
                return ["working periods must be non-negative whole numbers"]
            values.append(int(value))
        if len(set(values)) != len(values):
            return ["working periods must not repeat"]
        acts = inp.get("activities")
        if not isinstance(acts, list) or not acts:
            return ["at least one activity is required"]
        seen = set()
        for i, a in enumerate(acts, 1):
            if not isinstance(a, dict):
                return ["activity %d must be an object" % i]
            aid = str(a.get("id") or "").strip()
            if not re.fullmatch(r"[A-Za-z0-9_\-]{1,20}", aid) or aid in seen:
                return ["activity %d needs a unique id of 1-20 letters, digits, - or _" % i]
            seen.add(aid)
            if "duration" not in a or D(str(a["duration"])) < 0 or D(str(a["duration"])) != D(str(a["duration"])).to_integral_value():
                return ["activity " + aid + " needs a whole, non-negative duration"]
        for a in acts:
            for p in str(a.get("predecessors") or "").split(","):
                if p.strip() and p.strip() not in seen:
                    return ["activity %s cites unknown predecessor %s" % (str(a["id"]).strip(), p.strip())]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["calendar inputs are malformed; provide working_periods and activities with id and duration"]


def calendar_schedule_caveats(out, th):
    return ["The calendar is a declared list of working period numbers; no dates, weekends, holidays or shifts are inferred.",
            "Durations are counted in working periods and an activity cannot start or finish inside a non-working gap.",
            "One calendar applies to the whole project; per-activity calendars and resource limits are not modelled."]


def calendar_schedule_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    return ("With the declared working calendar, the project finishes in " + tok("project_duration") +
            " calendar periods, using " + tok("working_periods") + " working periods, with " +
            tok("critical_count") + " of " + tok("activity_count") + " activities on the critical path.")


def _multi_project_core(inp):
    capacity = {}
    for r in inp["resources"]:
        name = _act_id(r.get("name"))
        cap = _whole(r.get("capacity"), "resource " + name + " capacity")
        if cap <= 0:
            raise DataError("resource " + name + " capacity must be positive")
        capacity[name] = cap
    projects, seen_projects = [], set()
    for raw in inp["projects"]:
        name = _act_id(raw.get("name"))
        if name in seen_projects:
            raise DataError("duplicate project name " + name)
        seen_projects.add(name)
        priority = D(str(raw.get("priority", "1")))
        net = _cpm_network(raw["activities"])
        activities = []
        for a in raw["activities"]:
            aid = _act_id(a.get("id"))
            res = _act_id(a.get("resource"))
            if res not in capacity:
                raise DataError("activity %s/%s cites unknown resource %s" % (name, aid, res))
            amount = _whole(a.get("demand"), "activity " + aid + " demand")
            if amount < 0 or amount > capacity[res]:
                raise DataError("activity %s/%s demand must be between 0 and the capacity of %s" % (name, aid, res))
            activities.append({"project": name, "id": aid, "key": name + "_" + aid,
                               "duration": _whole(net["nodes"][aid]["dur"], "activity " + aid + " duration"),
                               "resource": res, "demand": amount,
                               "preds": net["nodes"][aid]["preds"], "es": net["es"][aid]})
        projects.append({"name": name, "priority": priority, "activities": activities,
                         "cpm_duration": net["duration"]})
    return capacity, projects


def multi_project_schedule_impl(inp):
    capacity, projects = _multi_project_core(inp)
    sequence = sorted(
        [a for project in projects for a in project["activities"]],
        key=lambda a: (next(p["priority"] for p in projects if p["name"] == a["project"]),
                       a["es"], -a["duration"], a["project"], a["id"]))
    starts, by_key = {}, {a["key"]: a for a in sequence}
    for activity in sequence:
        earliest = int(activity["es"])
        for pred in activity["preds"]:
            earliest = max(earliest, starts[activity["project"] + "_" + pred]
                           + by_key[activity["project"] + "_" + pred]["duration"])
        start = earliest
        while True:
            peers = {k: (s, by_key[k]["duration"]) for k, s in starts.items()
                     if by_key[k]["resource"] == activity["resource"]}
            if _fits(peers, {k: by_key[k]["demand"] for k in peers}, capacity[activity["resource"]],
                     start, activity["duration"], extra=activity["demand"]):
                break
            start += 1
        starts[activity["key"]] = start
    finishes = {a["key"]: starts[a["key"]] + a["duration"] for a in sequence}
    overall = max(finishes.values())
    out = {"overall_duration": D(overall), "project_count": D(len(projects)),
           "activity_count": D(len(sequence))}
    for project in projects:
        finish = max(finishes[a["key"]] for a in project["activities"])
        out["finish_" + project["name"]] = D(finish)
        out["delay_" + project["name"]] = D(finish) - project["cpm_duration"]
        for activity in project["activities"]:
            out["start_" + activity["key"]] = D(starts[activity["key"]])
            out["finish_" + activity["key"]] = D(finishes[activity["key"]])
    return out


def _multi_project_float(inp):
    capacity = {str(r["name"]).strip(): int(float(D(str(r["capacity"])))) for r in inp["resources"]}
    projects = []
    for raw in inp["projects"]:
        name = str(raw["name"]).strip()
        acts = []
        for a in raw["activities"]:
            acts.append({"project": name, "key": name + "_" + str(a["id"]).strip(),
                         "id": str(a["id"]).strip(),
                         "duration": int(float(D(str(a["duration"])))),
                         "resource": str(a["resource"]).strip(),
                         "demand": int(float(D(str(a["demand"])))),
                         "preds": [p.strip() for p in str(a.get("predecessors") or "").split(",") if p.strip()]})
        # forward early starts by repeated relaxation in input order
        es = {}
        pending = {a["id"]: a for a in acts}
        while pending:
            moved = False
            for aid in list(pending):
                a = pending[aid]
                if all(a["project"] + "_" + p in es for p in a["preds"]):
                    es[a["key"]] = max([es[a["project"] + "_" + p] + next(
                        x["duration"] for x in acts if x["key"] == a["project"] + "_" + p) for p in a["preds"]] or [0])
                    del pending[aid]
                    moved = True
            if not moved:
                raise ValueError("cycle")
        projects.append({"name": name, "priority": float(D(str(raw.get("priority", "1")))),
                         "activities": [{**a, "es": es[a["key"]]} for a in acts]})
    sequence = sorted([a for p in projects for a in p["activities"]],
                      key=lambda a: (next(p["priority"] for p in projects if p["name"] == a["project"]),
                                     a["es"], -a["duration"], a["project"], a["id"]))
    by_key = {a["key"]: a for a in sequence}
    starts = {}
    for a in sequence:
        start = max([a["es"]] + [starts[a["project"] + "_" + p] + by_key[a["project"] + "_" + p]["duration"]
                                 for p in a["preds"]])
        peers = {k: (s, by_key[k]["duration"]) for k, s in starts.items() if by_key[k]["resource"] == a["resource"]}
        while not _fits(peers, {k: by_key[k]["demand"] for k in peers}, capacity[a["resource"]],
                        start, a["duration"], extra=a["demand"]):
            start += 1
        starts[a["key"]] = start
    return {"overall_duration": max(starts[k] + by_key[k]["duration"] for k in starts),
            "finish": {p["name"]: max(starts[a["key"]] + a["duration"] for a in p["activities"]) for p in projects},
            "starts": starts}


def multi_project_schedule_tests(inp, impl):
    base, ref = impl(inp), _multi_project_float(inp)
    capacity, projects = _multi_project_core(inp)
    sequence = [a for project in projects for a in project["activities"]]
    starts = {a["key"]: int(base["start_" + a["key"]]) for a in sequence}
    finishes = {a["key"]: int(base["finish_" + a["key"]]) for a in sequence}
    peak_ok = True
    for name, cap in capacity.items():
        used = {a["key"]: (starts[a["key"]], a["duration"]) for a in sequence if a["resource"] == name}
        demand_used = {a["key"]: a["demand"] for a in sequence if a["resource"] == name}
        _, over = _load_by_period(used, demand_used, cap)
        peak_ok = peak_ok and over == 0
    checks = [
        ("second_implementation_agrees", _close(base["overall_duration"], ref["overall_duration"], rel=1e-9)
         and all(_close(base["finish_" + p["name"]], ref["finish"][p["name"]], rel=1e-9) for p in projects),
         "float route agrees with the Decimal route"),
        ("no_period_exceeds_a_resource_capacity", peak_ok, "no resource is over capacity after scheduling"),
        ("precedence_within_each_project_is_respected",
         all(starts[a["project"] + "_" + a["id"]] >= finishes[a["project"] + "_" + p]
             for a in sequence for p in a["preds"]), "every activity starts after its own predecessors"),
        ("no_project_finishes_before_its_unconstrained_duration",
         all(base["finish_" + p["name"]] >= p["cpm_duration"] for p in projects),
         "shared resources cannot make a project finish earlier than its own CPM"),
        ("every_activity_is_scheduled_exactly_once",
         len(starts) == len(sequence) and all(a["key"] in starts for a in sequence),
         "each project activity appears once"),
    ]
    return [(name, ok) for name, ok, _ in checks]


def multi_project_schedule_profile(inp):
    try:
        resources, projects = inp.get("resources"), inp.get("projects")
        if not isinstance(resources, list) or not resources:
            return ["at least one resource is required"]
        names = {str(r.get("name") or "").strip() for r in resources}
        if len(names) != len(resources):
            return ["resource names must be unique"]
        if not isinstance(projects, list) or not projects:
            return ["at least one project is required"]
        seen = set()
        for i, project in enumerate(projects, 1):
            if not isinstance(project, dict):
                return ["project %d must be an object" % i]
            name = str(project.get("name") or "").strip()
            if not re.fullmatch(r"[A-Za-z0-9_\-]{1,20}", name) or name in seen:
                return ["project %d needs a unique name of 1-20 letters, digits, - or _" % i]
            seen.add(name)
            if not isinstance(project.get("activities"), list) or not project["activities"]:
                return ["project " + name + " needs at least one activity"]
            ids = set()
            for a in project["activities"]:
                aid = str(a.get("id") or "").strip()
                if not re.fullmatch(r"[A-Za-z0-9_\-]{1,20}", aid) or aid in ids:
                    return ["project %s needs unique activity ids" % name]
                ids.add(aid)
                if str(a.get("resource", "")).strip() not in names:
                    return ["activity %s/%s cites an unknown resource" % (name, aid)]
                if D(str(a.get("duration", ""))) < 0:
                    return ["activity %s/%s needs a non-negative duration" % (name, aid)]
            for a in project["activities"]:
                for p in str(a.get("predecessors") or "").split(","):
                    if p.strip() and p.strip() not in ids:
                        return ["activity %s/%s cites unknown predecessor %s" % (name, str(a["id"]).strip(), p.strip())]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["multi-project inputs are malformed; every project needs a name and activities with resource and demand"]


def _multi_project_typing(metric):
    if metric in ("project_count", "activity_count"):
        return ("count", 0)
    return ("periods", 2)


def multi_project_schedule_caveats(out, th):
    return ["Projects are sequenced by declared priority, then early start, longest duration and id; a different priority changes the plan.",
            "One resource per activity, whole-period durations and demands, no preemption, no calendars and no inter-project dependencies.",
            "Shared resources delay projects; the reported delay is against each project's own unconstrained CPM duration."]


def multi_project_schedule_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    return ("The shared-resource plan finishes in " + tok("overall_duration") + " periods across " +
            tok("project_count") + " projects and " + tok("activity_count") + " activities.")


def _pert_draw(rng, low, mode, high):
    if high == low:
        return low
    u = rng.random()
    split = (mode - low) / (high - low)
    if u < split:
        return low + math.sqrt(u * (high - low) * (mode - low))
    return high - math.sqrt((1.0 - u) * (high - low) * (high - mode))


def _percentile(values, pct):
    ordered = sorted(values)
    index = max(0, min(len(ordered) - 1, int(math.ceil(pct / 100.0 * len(ordered))) - 1))
    return ordered[index]


def schedule_risk_impl(inp):
    activities = inp["activities"]
    iterations = int(inp.get("iterations", 1000))
    seed = int(inp.get("seed", 0))
    if iterations < 1 or iterations > 5000:
        raise DataError("iterations must be between 1 and 5000")
    nodes, order = {}, []
    for a in activities:
        aid = _act_id(a.get("id"))
        if aid in nodes:
            raise DataError("duplicate activity id " + aid)
        o, m, p = (D(str(a[k])) for k in ("optimistic", "most_likely", "pessimistic"))
        if o < 0 or not (o <= m <= p):
            raise DataError("activity " + aid + " needs 0 <= optimistic <= most_likely <= pessimistic")
        preds = [x.strip() for x in str(a.get("predecessors") or "").split(",") if x.strip()]
        nodes[aid] = {"o": float(o), "m": float(m), "p": float(p), "preds": preds}
        order.append(aid)
    for aid, node in nodes.items():
        for p in node["preds"]:
            if p not in nodes:
                raise DataError("activity " + aid + " cites unknown predecessor " + p)
    succ = {aid: [] for aid in nodes}
    indeg = {aid: len(n["preds"]) for aid, n in nodes.items()}
    for aid, n in nodes.items():
        for p in n["preds"]:
            succ[p].append(aid)
    queue = [aid for aid in order if indeg[aid] == 0]
    topo = []
    while queue:
        aid = queue.pop(0)
        topo.append(aid)
        for s in succ[aid]:
            indeg[s] -= 1
            if indeg[s] == 0:
                queue.append(s)
    if len(topo) != len(nodes):
        raise DataError("the predecessor graph contains a cycle")
    rng = random.Random(seed)
    durations, samples, critical = [], {aid: [] for aid in nodes}, {aid: 0 for aid in nodes}
    for _ in range(iterations):
        span = {aid: _pert_draw(rng, nodes[aid]["o"], nodes[aid]["m"], nodes[aid]["p"]) for aid in order}
        for aid in order:
            samples[aid].append(span[aid])
        es, ef = {}, {}
        for aid in topo:
            es[aid] = max((ef[p] for p in nodes[aid]["preds"]), default=0.0)
            ef[aid] = es[aid] + span[aid]
        duration = max(ef.values())
        durations.append(duration)
        ls, lf = {}, {}
        for aid in reversed(topo):
            lf[aid] = min((ls[s] for s in succ[aid]), default=duration)
            ls[aid] = lf[aid] - span[aid]
        for aid in order:
            if ls[aid] - (ef[aid] - span[aid]) <= 1e-12:
                critical[aid] += 1
    target = inp.get("target_duration")
    target = None if target in (None, "") else D(str(target))
    out = {"iterations": D(iterations), "mean_duration": D(str(sum(durations) / len(durations))),
           "p50_duration": D(str(_percentile(durations, 50))), "p80_duration": D(str(_percentile(durations, 80))),
           "p90_duration": D(str(_percentile(durations, 90))), "min_duration": D(str(min(durations))),
           "max_duration": D(str(max(durations)))}
    if target is not None:
        within = sum(1 for value in durations if value <= float(target))
        out["n_within_target"] = D(within)
        out["probability_within_target"] = D(str(within / iterations))
    for aid in order:
        out["criticality_" + aid] = D(str(critical[aid] / iterations))
        out["sample_min_" + aid] = D(str(min(samples[aid])))
        out["sample_max_" + aid] = D(str(max(samples[aid])))
    return out


def _risk_float(inp):
    activities = inp["activities"]
    iterations = int(inp.get("iterations", 1000))
    seed = int(inp.get("seed", 0))
    nodes, order = {}, []
    for a in activities:
        aid = str(a["id"]).strip()
        nodes[aid] = {"o": float(D(str(a["optimistic"]))), "m": float(D(str(a["most_likely"]))),
                      "p": float(D(str(a["pessimistic"]))),
                      "preds": [x.strip() for x in str(a.get("predecessors") or "").split(",") if x.strip()]}
        order.append(aid)
    rng = random.Random(seed)
    durations = []
    for _ in range(iterations):
        span = {aid: _pert_draw(rng, nodes[aid]["o"], nodes[aid]["m"], nodes[aid]["p"]) for aid in order}
        ef, pending = {}, dict(nodes)
        while pending:
            moved = False
            for aid in list(pending):
                if all(p in ef for p in nodes[aid]["preds"]):
                    ef[aid] = max((ef[p] for p in nodes[aid]["preds"]), default=0.0) + span[aid]
                    del pending[aid]
                    moved = True
            if not moved:
                raise ValueError("cycle")
        durations.append(max(ef.values()))
    return {"mean_duration": sum(durations) / len(durations), "p50_duration": _percentile(durations, 50),
            "p80_duration": _percentile(durations, 80), "p90_duration": _percentile(durations, 90),
            "min_duration": min(durations), "max_duration": max(durations)}


def schedule_risk_tests(inp, impl):
    base, ref = impl(inp), _risk_float(inp)
    repeat = impl(inp)
    bounds_ok = all(base["sample_min_" + aid] >= D(str(next(a for a in inp["activities"] if str(a["id"]).strip() == aid)["optimistic"]))
                    and base["sample_max_" + aid] <= D(str(next(a for a in inp["activities"] if str(a["id"]).strip() == aid)["pessimistic"]))
                    for aid in [str(a["id"]).strip() for a in inp["activities"]])
    probability_ok = True
    if "n_within_target" in base:
        probability_ok = _close(base["probability_within_target"], base["n_within_target"] / base["iterations"], rel=1e-9)
    checks = [
        ("second_implementation_and_seed_agree",
         all(_close(base[k], ref[k], rel=1e-9) for k in ("mean_duration", "p50_duration", "p80_duration", "p90_duration"))
         and base["mean_duration"] == repeat["mean_duration"] and base["p80_duration"] == repeat["p80_duration"],
         "the float route and a repeated run with the same seed agree"),
        ("sampled_durations_stay_within_the_declared_bounds", bounds_ok,
         "every sampled activity duration is between its optimistic and pessimistic values"),
        ("percentiles_are_ordered", base["p50_duration"] <= base["p80_duration"] <= base["p90_duration"]
         <= base["max_duration"], "P50 <= P80 <= P90 <= maximum"),
        ("the_mean_lies_between_the_observed_extremes",
         base["min_duration"] <= base["mean_duration"] <= base["max_duration"], "the mean is inside the sampled range"),
        ("the_target_probability_matches_the_sample_count", probability_ok,
         "the probability is the counted fraction of iterations within the target"),
        ("criticality_indices_are_fractions",
         all(D(0) <= base["criticality_" + aid] <= D(1) for aid in [str(a["id"]).strip() for a in inp["activities"]])
         and any(base["criticality_" + aid] > 0 for aid in [str(a["id"]).strip() for a in inp["activities"]]),
         "each criticality index is a fraction and at least one activity is critical in some run"),
    ]
    return [(name, ok) for name, ok, _ in checks]


def schedule_risk_profile(inp):
    try:
        acts = inp.get("activities")
        if not isinstance(acts, list) or not acts:
            return ["at least one activity is required"]
        ids = set()
        for i, a in enumerate(acts, 1):
            aid = str(a.get("id") or "").strip()
            if not re.fullmatch(r"[A-Za-z0-9_\-]{1,20}", aid) or aid in ids:
                return ["activity %d needs a unique id of 1-20 letters, digits, - or _" % i]
            ids.add(aid)
            try:
                o, m, p = (D(str(a[k])) for k in ("optimistic", "most_likely", "pessimistic"))
            except (InvalidOperation, ValueError, TypeError, KeyError):
                return ["activity " + aid + " needs optimistic, most_likely and pessimistic numbers"]
            if o < 0 or not (o <= m <= p):
                return ["activity " + aid + " needs 0 <= optimistic <= most_likely <= pessimistic"]
        for a in acts:
            for p in str(a.get("predecessors") or "").split(","):
                if p.strip() and p.strip() not in ids:
                    return ["activity %s cites unknown predecessor %s" % (str(a["id"]).strip(), p.strip())]
        iterations = int(inp.get("iterations", 1000))
        if iterations < 1 or iterations > 5000:
            return ["iterations must be between 1 and 5000"]
        if int(inp.get("seed", 0)) < 0:
            return ["seed must be a non-negative integer"]
        if inp.get("target_duration") not in (None, "") and D(str(inp["target_duration"])) <= 0:
            return ["target_duration must be positive when supplied"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["schedule-risk inputs are malformed; every activity needs optimistic, most_likely and pessimistic durations"]


def _schedule_risk_typing(metric):
    if metric == "iterations" or metric == "n_within_target":
        return ("count", 0)
    if metric.startswith("criticality_") or metric.startswith("probability_"):
        return ("ratio", 4)
    return ("periods", 2)


def schedule_risk_caveats(out, th):
    return ["Durations are independent triangular draws between the optimistic and pessimistic values with the most likely as the mode; that distribution is a declared convention.",
            "The simulation is seeded and reproducible, but a different seed gives different percentiles; it is not a forecast or a guarantee.",
            "Resource limits, calendars and correlated durations are not modelled; the criticality index is the share of runs in which an activity had zero float."]


def schedule_risk_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    text = ("Across " + tok("iterations") + " seeded simulations the mean duration is " + tok("mean_duration") +
            ", with median " + tok("p50_duration") + ", eightieth percentile " + tok("p80_duration") +
            " and ninetieth percentile " + tok("p90_duration") + ".")
    if "probability_within_target" in out:
        text += " The share of runs within the target is " + tok("probability_within_target") + "."
    return text


def _tree_node(node, depth=0):
    if not isinstance(node, dict) or depth > 12:
        raise DataError("each tree node must be an object, nested at most twelve deep")
    kind = str(node.get("type") or "").strip()
    if kind == "terminal":
        try:
            value = D(str(node["value"]))
        except (InvalidOperation, ValueError, TypeError, KeyError):
            raise DataError("a terminal node needs a numeric value")
        return {"kind": "terminal", "value": value}
    if kind == "decision":
        raw = node.get("alternatives")
        if not isinstance(raw, list) or not raw:
            raise DataError("a decision node needs at least one alternative")
        return {"kind": "decision", "alternatives": [
            {"name": str(item.get("name") or ("Alternative %d" % (index + 1))),
             "node": _tree_node(item.get("node"), depth + 1)}
            for index, item in enumerate(raw)]}
    if kind == "chance":
        raw = node.get("branches")
        if not isinstance(raw, list) or not raw:
            raise DataError("a chance node needs at least one branch")
        branches, total = [], D(0)
        for index, item in enumerate(raw):
            try:
                probability = D(str(item["probability"]))
            except (InvalidOperation, ValueError, TypeError, KeyError):
                raise DataError("chance branch %d needs a numeric probability" % (index + 1))
            if probability < 0 or probability > 1:
                raise DataError("chance branch %d probability must be between zero and one" % (index + 1))
            total += probability
            branches.append({"probability": probability, "node": _tree_node(item.get("node"), depth + 1)})
        if total != 1:
            raise DataError("the probabilities at a chance node must sum to one (found %s)" % total)
        return {"kind": "chance", "branches": branches}
    raise DataError("node type must be decision, chance or terminal")


def _tree_eval(node):
    """Return (expected value, terminal paths [(probability, value)], terminal count)."""
    if node["kind"] == "terminal":
        return node["value"], [(D(1), node["value"])], 1
    if node["kind"] == "chance":
        ev, paths, count = D(0), [], 0
        for branch in node["branches"]:
            child_ev, child_paths, child_count = _tree_eval(branch["node"])
            ev += branch["probability"] * child_ev
            paths += [(branch["probability"] * p, v) for p, v in child_paths]
            count += child_count
        return ev, paths, count
    options = [(_tree_eval(alt["node"]), alt["name"]) for alt in node["alternatives"]]
    best = max(options, key=lambda item: (item[0][0], -len(item[1])))
    return best[0][0], best[0][1], sum(item[0][2] for item in options)


def decision_tree_impl(inp):
    root = _tree_node(inp.get("tree"))
    if root["kind"] != "decision":
        raise DataError("the root of a decision tree must be a decision node")
    alternatives = []
    for alt in root["alternatives"]:
        ev, paths, count = _tree_eval(alt["node"])
        alternatives.append({"name": alt["name"], "ev": ev, "paths": paths, "count": count})
    best = max(range(len(alternatives)), key=lambda i: (alternatives[i]["ev"], -i))
    out = {"expected_value": alternatives[best]["ev"], "best_index": D(best + 1),
           "alternative_count": D(len(alternatives)),
           "terminal_count": D(sum(alt["count"] for alt in alternatives))}
    for index, alt in enumerate(alternatives, 1):
        out["ev_" + str(index)] = alt["ev"]
        out["loss_probability_" + str(index)] = sum((p for p, value in alt["paths"] if value < 0), D(0))
        out["worst_value_" + str(index)] = min(value for _, value in alt["paths"])
        out["best_value_" + str(index)] = max(value for _, value in alt["paths"])
    return out


def _tree_float(node):
    if node["type"] == "terminal":
        return float(D(str(node["value"]))), 1
    if node["type"] == "chance":
        ev, count = 0.0, 0
        for branch in node["branches"]:
            child, child_count = _tree_float(branch["node"])
            ev += float(D(str(branch["probability"]))) * child
            count += child_count
        return ev, count
    best, count = None, 0
    for alt in node["alternatives"]:
        value, child_count = _tree_float(alt["node"])
        count += child_count
        best = value if best is None else max(best, value)
    return best, count


def decision_tree_tests(inp, impl):
    base = impl(inp)
    ref, _ = _tree_float(inp["tree"])
    root = _tree_node(inp["tree"])
    alternatives = [_tree_eval(alt["node"])[0] for alt in root["alternatives"]]
    recounted = max(alternatives)
    probabilities_ok = True
    def walk(node):
        nonlocal probabilities_ok
        if node["kind"] == "chance":
            probabilities_ok = probabilities_ok and sum(b["probability"] for b in node["branches"]) == 1
            for branch in node["branches"]:
                walk(branch["node"])
        elif node["kind"] == "decision":
            for alt in node["alternatives"]:
                walk(alt["node"])
    walk(root)
    checks = [
        ("second_implementation_agrees", _close(base["expected_value"], ref, rel=1e-9),
         "float route agrees with the Decimal route"),
        ("chance_probabilities_sum_to_one", probabilities_ok, "every chance node sums to one"),
        ("the_root_value_is_the_best_alternative", base["expected_value"] == recounted,
         "the root value is the maximum of the alternative expected values"),
        ("every_alternative_has_a_probability_and_a_range",
         all(D(0) <= base["loss_probability_" + str(i)] <= D(1) for i in range(1, len(alternatives) + 1))
         and all(base["worst_value_" + str(i)] <= base["ev_" + str(i)] <= base["best_value_" + str(i)]
                 for i in range(1, len(alternatives) + 1)),
         "loss probability is a fraction and the expected value lies in its range"),
        ("the_best_index_points_to_the_highest_value",
         base["ev_" + str(int(base["best_index"]))] == base["expected_value"],
         "the reported best alternative carries the root value"),
    ]
    return [(name, ok) for name, ok, _ in checks]


def decision_tree_profile(inp):
    try:
        root = _tree_node(inp.get("tree"))
        if root["kind"] != "decision":
            return ["the root of a decision tree must be a decision node"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["decision-tree inputs are malformed; each node needs a type and its children"]


def _tree_typing(metric):
    if metric in ("best_index", "alternative_count", "terminal_count"):
        return ("count", 0)
    if metric.startswith("loss_probability_"):
        return ("ratio", 4)
    return ("currency", 2)


def decision_tree_caveats(out, th):
    return ["The tree, its probabilities and its terminal values are yours; the method only multiplies and adds them.",
            "No probability is inferred, no branch is pruned and no recommendation is added beyond the highest expected value.",
            "Expected value ignores risk aversion; the loss probability and the range are reported beside it."]


def decision_tree_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    return ("The best alternative is number " + tok("best_index") + ", with an expected value of " +
            tok("expected_value") + " across " + tok("terminal_count") + " terminal outcomes.")


def real_option_impl(inp):
    s0, strike = D(str(inp["underlying_value"])), D(str(inp["investment_cost"]))
    sigma, rate = D(str(inp["volatility"])), D(str(inp["risk_free_rate"]))
    steps = _whole(inp.get("steps", 5), "steps")
    horizon = D(str(inp.get("horizon_years", 1)))
    kind = str(inp.get("option_type", "call"))
    exercise = str(inp.get("exercise", "european"))
    if s0 <= 0 or strike <= 0 or sigma <= 0 or horizon <= 0:
        raise DataError("underlying_value, investment_cost, volatility and horizon_years must be positive")
    if steps < 1 or steps > 200:
        raise DataError("steps must be between 1 and 200")
    if kind not in ("call", "put") or exercise not in ("european", "american"):
        raise DataError("option_type must be call or put and exercise must be european or american")
    dt = horizon / D(steps)
    up = (sigma * dt.sqrt()).exp()
    down = D(1) / up
    growth = (rate * dt).exp()
    probability = (growth - down) / (up - down)
    if not (D(0) < probability < D(1)):
        raise DataError("the risk-neutral probability is outside zero and one; check the rate and volatility")
    discount = (-rate * dt).exp()
    values = []
    for node in range(steps + 1):
        price = s0 * (up ** node) * (down ** (steps - node))
        values.append(max(price - strike, D(0)) if kind == "call" else max(strike - price, D(0)))
    level_one = None
    for level in range(steps - 1, -1, -1):
        for node in range(level + 1):
            values[node] = discount * (probability * values[node + 1] + (D(1) - probability) * values[node])
            if exercise == "american":
                price = s0 * (up ** node) * (down ** (level - node))
                intrinsic = max(price - strike, D(0)) if kind == "call" else max(strike - price, D(0))
                values[node] = max(values[node], intrinsic)
        if level == 1:
            level_one = (values[0], values[1])
    value = values[0]
    price_up, price_down = s0 * up, s0 * down
    delta = (level_one[1] - level_one[0]) / (price_up - price_down)
    intrinsic = max(s0 - strike, D(0)) if kind == "call" else max(strike - s0, D(0))
    return {"option_value": value, "intrinsic_value": intrinsic, "delta": delta, "up_factor": up,
            "down_factor": down, "risk_neutral_probability": probability, "steps": D(steps),
            "terminal_nodes": D(steps + 1)}


def _real_option_float(inp):
    s0, strike = float(D(str(inp["underlying_value"]))), float(D(str(inp["investment_cost"])))
    sigma, rate = float(D(str(inp["volatility"]))), float(D(str(inp["risk_free_rate"])))
    steps = int(float(D(str(inp.get("steps", 5)))))
    horizon = float(D(str(inp.get("horizon_years", 1))))
    kind, exercise = str(inp.get("option_type", "call")), str(inp.get("exercise", "european"))
    dt = horizon / steps
    up = math.exp(sigma * math.sqrt(dt)); down = 1.0 / up
    probability = (math.exp(rate * dt) - down) / (up - down)
    discount = math.exp(-rate * dt)
    values = []
    for node in range(steps + 1):
        price = s0 * up ** node * down ** (steps - node)
        values.append(max(price - strike, 0.0) if kind == "call" else max(strike - price, 0.0))
    for level in range(steps - 1, -1, -1):
        for node in range(level + 1):
            values[node] = discount * (probability * values[node + 1] + (1 - probability) * values[node])
            if exercise == "american":
                price = s0 * up ** node * down ** (level - node)
                intrinsic = max(price - strike, 0.0) if kind == "call" else max(strike - price, 0.0)
                values[node] = max(values[node], intrinsic)
    return {"option_value": values[0], "up_factor": up, "risk_neutral_probability": probability}


def real_option_tests(inp, impl):
    base, ref = impl(inp), _real_option_float(inp)
    kind, exercise = str(inp.get("option_type", "call")), str(inp.get("exercise", "european"))
    checks = [
        ("second_implementation_agrees",
         _close(base["option_value"], ref["option_value"], rel=1e-9)
         and _close(base["up_factor"], ref["up_factor"], rel=1e-9)
         and _close(base["risk_neutral_probability"], ref["risk_neutral_probability"], rel=1e-9),
         "float route agrees with the Decimal route"),
        ("the_option_is_worth_at_least_its_intrinsic_value",
         (exercise != "american") or base["option_value"] >= base["intrinsic_value"],
         "an American option cannot be worth less than exercising it now"),
        ("the_value_respects_its_upper_bound",
         base["option_value"] <= (D(str(inp["underlying_value"])) if kind == "call" else D(str(inp["investment_cost"]))),
         "a call cannot exceed the underlying and a put cannot exceed the strike"),
        ("the_risk_neutral_probability_is_a_probability",
         D(0) < base["risk_neutral_probability"] < D(1) and base["up_factor"] > 1 > base["down_factor"],
         "the lattice has a valid up factor, down factor and probability"),
        ("delta_has_the_sign_of_the_option",
         (kind == "call" and D(0) <= base["delta"] <= D(1)) or (kind == "put" and D(-1) <= base["delta"] <= D(0)),
         "call delta is between zero and one; put delta is between minus one and zero"),
    ]
    return [(name, ok) for name, ok, _ in checks]


def real_option_profile(inp):
    try:
        s0 = D(str(inp.get("underlying_value", "")))
        strike = D(str(inp.get("investment_cost", "")))
        sigma = D(str(inp.get("volatility", "")))
        horizon = D(str(inp.get("horizon_years", 1)))
        steps = D(str(inp.get("steps", 5)))
        if s0 <= 0 or strike <= 0 or sigma <= 0 or horizon <= 0:
            return ["underlying_value, investment_cost, volatility and horizon_years must be positive"]
        if steps != steps.to_integral_value() or steps < 1 or steps > 200:
            return ["steps must be a whole number between 1 and 200"]
        if str(inp.get("option_type", "call")) not in ("call", "put"):
            return ["option_type must be call or put"]
        if str(inp.get("exercise", "european")) not in ("european", "american"):
            return ["exercise must be european or american"]
        return []
    except (InvalidOperation, ValueError, TypeError):
        return ["real-option inputs are malformed; provide underlying_value, investment_cost, volatility and risk_free_rate"]


def _real_option_typing(metric):
    if metric in ("steps", "terminal_nodes"):
        return ("count", 0)
    if metric in ("delta", "risk_neutral_probability", "up_factor", "down_factor"):
        return ("ratio", 6)
    return ("currency", 2)


def real_option_caveats(out, th):
    return ["The lattice is a Cox-Ross-Rubinstein binomial with a declared volatility, rate, horizon and step count; the project value and investment are yours.",
            "A real option is not a traded option: no market price, no continuous hedging and no replication argument is available.",
            "More steps change the value slightly; the model does not calibrate volatility or estimate the underlying distribution."]


def real_option_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    return ("The option value is " + tok("option_value") + " against an intrinsic value of " +
            tok("intrinsic_value") + ", with a delta of " + tok("delta") + " on " + tok("steps") + " steps.")


def multi_criteria_impl(inp):
    criteria = inp["criteria"]
    alternatives = inp["alternatives"]
    scale = D(str(inp.get("scale_max", "10")))
    if scale <= 0:
        raise DataError("scale_max must be positive")
    names, total = set(), D(0)
    for criterion in criteria:
        name = _act_id(criterion.get("name"))
        if name in names:
            raise DataError("duplicate criterion " + name)
        names.add(name)
        weight = D(str(criterion.get("weight")))
        if weight < 0:
            raise DataError("criterion " + name + " weight must be non-negative")
        total += weight
    if total != 1:
        raise DataError("criterion weights must sum to one (found %s)" % total)
    totals = {}
    for index, alt in enumerate(alternatives, 1):
        scores = alt.get("scores") or {}
        if set(scores) != names:
            raise DataError("alternative %d must score every criterion exactly once" % index)
        value = D(0)
        for criterion in criteria:
            name = str(criterion["name"]).strip()
            score = D(str(scores[name]))
            if score < 0 or score > scale:
                raise DataError("score for %s on %s must be between zero and %s" % (alt.get("name"), name, scale))
            value += D(str(criterion["weight"])) * score
        totals[index] = value
    ranked = sorted(totals, key=lambda i: (-totals[i], i))
    out = {"best_index": D(ranked[0]), "best_total": totals[ranked[0]],
           "alternative_count": D(len(alternatives)), "criteria_count": D(len(criteria)), "weight_sum": total}
    for index in totals:
        out["total_" + str(index)] = totals[index]
        out["rank_" + str(index)] = D(ranked.index(index) + 1)
    return out


def _multi_criteria_float(inp):
    criteria = [(str(c["name"]).strip(), float(D(str(c["weight"])))) for c in inp["criteria"]]
    totals = {}
    for index, alt in enumerate(inp["alternatives"], 1):
        totals[index] = sum(weight * float(D(str(alt["scores"][name]))) for name, weight in criteria)
    return totals


def multi_criteria_tests(inp, impl):
    base, ref = impl(inp), _multi_criteria_float(inp)
    totals = {i: base["total_" + str(i)] for i in range(1, len(inp["alternatives"]) + 1)}
    ranks = [int(base["rank_" + str(i)]) for i in range(1, len(inp["alternatives"]) + 1)]
    checks = [
        ("second_implementation_agrees",
         all(_close(totals[i], ref[i], rel=1e-9) for i in totals), "float route agrees with the Decimal route"),
        ("weights_sum_to_one", base["weight_sum"] == 1, "the declared criterion weights sum to one"),
        ("every_score_is_within_the_scale",
         all(D(0) <= D(str(a["scores"][c["name"]])) <= D(str(inp.get("scale_max", "10")))
             for a in inp["alternatives"] for c in inp["criteria"]), "every score is inside the declared scale"),
        ("each_total_is_the_weighted_sum",
         all(totals[i] == sum(D(str(c["weight"])) * D(str(inp["alternatives"][i - 1]["scores"][c["name"]]))
                             for c in inp["criteria"]) for i in totals), "the total is the weighted sum of the scores"),
        ("ranks_are_a_permutation_and_the_best_has_the_highest_total",
         sorted(ranks) == list(range(1, len(ranks) + 1))
         and totals[int(base["best_index"])] == max(totals.values()),
         "each alternative has one rank and the best index carries the highest total"),
    ]
    return [(name, ok) for name, ok, _ in checks]


def multi_criteria_profile(inp):
    try:
        criteria, alternatives = inp.get("criteria"), inp.get("alternatives")
        if not isinstance(criteria, list) or not criteria:
            return ["at least one criterion is required"]
        if not isinstance(alternatives, list) or len(alternatives) < 2:
            return ["at least two alternatives are required"]
        names, total = set(), D(0)
        for criterion in criteria:
            name = str(criterion.get("name") or "").strip()
            if not re.fullmatch(r"[A-Za-z0-9_\-]{1,20}", name) or name in names:
                return ["criterion names must be unique and use 1-20 letters, digits, - or _"]
            names.add(name)
            weight = D(str(criterion.get("weight", "")))
            if weight < 0:
                return ["criterion weights must be non-negative"]
            total += weight
        if total != 1:
            return ["criterion weights must sum to one"]
        for alt in alternatives:
            if not isinstance(alt.get("scores"), dict) or set(alt["scores"]) != names:
                return ["every alternative must score every criterion exactly once"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["multi-criteria inputs are malformed; provide criteria with weights and alternatives with scores"]


def _multi_criteria_typing(metric):
    if metric in ("best_index", "alternative_count", "criteria_count", "weight_sum") or metric.startswith("rank_"):
        return ("count", 0)
    return ("score", 4)


def multi_criteria_caveats(out, th):
    return ["The criteria, weights, scale and scores are yours; the method only multiplies and adds them.",
            "A weighted total is not a truth: weights encode your judgement, and a different weighting can reorder the alternatives.",
            "No score is inferred, no weight is optimised and no recommendation is made beyond the highest declared total."]


def multi_criteria_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    return ("Alternative number " + tok("best_index") + " has the highest weighted total of " +
            tok("best_total") + " across " + tok("criteria_count") + " criteria.")


MC_KINDS = ("fixed", "uniform", "triangular")


def _mc_distribution(row, name):
    kind = str(row.get("distribution", "fixed")).strip().lower()
    if kind not in MC_KINDS:
        raise DataError(name + " distribution must be fixed, uniform or triangular")
    if kind == "fixed":
        try:
            return {"kind": "fixed", "value": float(D(str(row["value"])))}
        except (InvalidOperation, ValueError, TypeError, KeyError):
            raise DataError(name + " needs a numeric value")
    if kind == "uniform":
        try:
            low, high = (float(D(str(row[k]))) for k in ("low", "high"))
        except (InvalidOperation, ValueError, TypeError, KeyError):
            raise DataError(name + " needs numeric low and high values")
        if low > high:
            raise DataError(name + " low must not exceed high")
        return {"kind": "uniform", "low": low, "high": high}
    try:
        low, mode, high = (float(D(str(row[k]))) for k in ("low", "mode", "high"))
    except (InvalidOperation, ValueError, TypeError, KeyError):
        raise DataError(name + " needs numeric low, mode and high values")
    if not (low <= mode <= high):
        raise DataError(name + " needs low <= mode <= high")
    return {"kind": "triangular", "low": low, "mode": mode, "high": high}


def _mc_draw(rng, dist):
    if dist["kind"] == "fixed":
        return dist["value"]
    if dist["kind"] == "uniform":
        return dist["low"] + rng.random() * (dist["high"] - dist["low"])
    return _pert_draw(rng, dist["low"], dist["mode"], dist["high"])


def _mc_setup(inp):
    iterations = int(inp.get("iterations", 1000))
    seed = int(inp.get("seed", 0))
    if iterations < 1 or iterations > 5000:
        raise DataError("iterations must be between 1 and 5000")
    if seed < 0:
        raise DataError("seed must be a non-negative integer")
    model = str(inp.get("model", "npv"))
    if model not in ("npv", "profit"):
        raise DataError("model must be npv or profit")
    if model == "npv":
        rate = float(D(str(inp.get("discount_rate", "0"))))
        rows = inp.get("cashflows")
        if not isinstance(rows, list) or not rows:
            raise DataError("an npv simulation needs at least one cash flow")
        flows = []
        for index, row in enumerate(rows, 1):
            name = str(row.get("name") or ("cashflow_%d" % index)).strip()
            period = int(row.get("period", index - 1))
            if period < 0:
                raise DataError("cash-flow periods must be non-negative")
            flows.append({"name": name, "period": period, "dist": _mc_distribution(row, name)})
        return model, iterations, seed, {"rate": rate, "flows": flows}
    variables = inp.get("variables")
    if not isinstance(variables, list) or not variables:
        raise DataError("a profit simulation needs price, variable_cost and volume variables")
    found = {}
    for row in variables:
        name = str(row.get("name") or "").strip().lower()
        if name not in ("price", "variable_cost", "volume"):
            raise DataError("profit variables must be named price, variable_cost or volume")
        if name in found:
            raise DataError("duplicate profit variable " + name)
        found[name] = _mc_distribution(row, name)
    if set(found) != {"price", "variable_cost", "volume"}:
        raise DataError("profit simulation needs exactly price, variable_cost and volume")
    return model, iterations, seed, {"variables": found, "fixed_cost": float(D(str(inp.get("fixed_cost", "0"))))}


def monte_carlo_impl(inp):
    model, iterations, seed, setup = _mc_setup(inp)
    rng = random.Random(seed)
    results, samples = [], {}
    for _ in range(iterations):
        if model == "npv":
            value = 0.0
            for flow in setup["flows"]:
                draw = _mc_draw(rng, flow["dist"])
                samples.setdefault(flow["name"], []).append(draw)
                value += draw / ((1 + setup["rate"]) ** flow["period"])
            results.append(value)
        else:
            draws = {}
            for name, dist in setup["variables"].items():
                draws[name] = _mc_draw(rng, dist)
                samples.setdefault(name, []).append(draws[name])
            results.append((draws["price"] - draws["variable_cost"]) * draws["volume"] - setup["fixed_cost"])
    positive = sum(1 for value in results if value > 0)
    out = {"iterations": D(iterations), "mean_result": D(str(sum(results) / len(results))),
           "p10_result": D(str(_percentile(results, 10))), "p50_result": D(str(_percentile(results, 50))),
           "p90_result": D(str(_percentile(results, 90))), "min_result": D(str(min(results))),
           "max_result": D(str(max(results))), "n_positive": D(positive),
           "probability_positive": D(str(positive / iterations))}
    for name, values in samples.items():
        out["sample_min_" + name] = D(str(min(values)))
        out["sample_max_" + name] = D(str(max(values)))
    return out


def _monte_carlo_float(inp):
    model, iterations, seed, setup = _mc_setup(inp)
    rng = random.Random(seed)
    results = []
    for _ in range(iterations):
        if model == "npv":
            results.append(sum(_mc_draw(rng, flow["dist"]) / ((1 + setup["rate"]) ** flow["period"])
                               for flow in setup["flows"]))
        else:
            draws = {name: _mc_draw(rng, dist) for name, dist in setup["variables"].items()}
            results.append((draws["price"] - draws["variable_cost"]) * draws["volume"] - setup["fixed_cost"])
    return {"mean_result": sum(results) / len(results), "p10_result": _percentile(results, 10),
            "p50_result": _percentile(results, 50), "p90_result": _percentile(results, 90),
            "min_result": min(results), "max_result": max(results)}


def monte_carlo_tests(inp, impl):
    base, ref = impl(inp), _monte_carlo_float(inp)
    repeat = impl(inp)
    bounded = True
    model, _iterations, _seed, setup = _mc_setup(inp)
    rows = ([(flow["name"], flow["dist"]) for flow in setup["flows"]] if model == "npv"
            else list(setup["variables"].items()))
    for name, dist in rows:
        if dist["kind"] in ("uniform", "triangular"):
            bounded = bounded and base["sample_min_" + name] >= D(str(dist["low"])) and base["sample_max_" + name] <= D(str(dist["high"]))
    checks = [
        ("second_implementation_and_seed_agree",
         all(_close(base[k], ref[k], rel=1e-9) for k in ("mean_result", "p10_result", "p50_result", "p90_result"))
         and base["mean_result"] == repeat["mean_result"] and base["p90_result"] == repeat["p90_result"],
         "the float route and a repeated run with the same seed agree"),
        ("sampled_inputs_stay_within_their_bounds", bounded,
         "every bounded draw is between its low and high values"),
        ("percentiles_are_ordered", base["p10_result"] <= base["p50_result"] <= base["p90_result"] <= base["max_result"],
         "P10 <= P50 <= P90 <= maximum"),
        ("the_mean_lies_between_the_observed_extremes",
         base["min_result"] <= base["mean_result"] <= base["max_result"], "the mean is inside the sampled range"),
        ("the_positive_probability_matches_the_count",
         _close(base["probability_positive"], base["n_positive"] / base["iterations"], rel=1e-9)
         and D(0) <= base["probability_positive"] <= D(1),
         "the probability is the counted fraction of positive results"),
    ]
    return [(name, ok) for name, ok, _ in checks]


def monte_carlo_profile(inp):
    try:
        model, iterations, seed, _setup = _mc_setup(inp)
        if model == "npv":
            if str(inp.get("discount_rate", "0")) == "":
                return ["discount_rate must be a number"]
            for row in inp["cashflows"]:
                if not str(row.get("name") or "").strip():
                    return ["every cash flow needs a name"]
        else:
            if D(str(inp.get("fixed_cost", "0"))) < 0:
                return ["fixed_cost must be non-negative"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["Monte Carlo inputs are malformed; provide a model, iterations, a seed and the declared distributions"]


def _monte_carlo_typing(metric):
    if metric in ("iterations", "n_positive"):
        return ("count", 0)
    if metric == "probability_positive":
        return ("ratio", 4)
    return ("currency", 2)


def monte_carlo_caveats(out, th):
    return ["The model is limited to NPV of declared cash flows or profit = (price - variable cost) x volume - fixed cost; no arbitrary formula is evaluated.",
            "Distributions are fixed, uniform or triangular, and every draw is independent; correlation and distribution fitting are not modelled.",
            "The simulation is seeded and reproducible, but a different seed changes the percentiles; it is not a forecast or a guarantee."]


def monte_carlo_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    return ("Across " + tok("iterations") + " seeded simulations the mean result is " + tok("mean_result") +
            ", with median " + tok("p50_result") + ", ninetieth percentile " + tok("p90_result") +
            " and a " + tok("probability_positive") + " share of positive results.")


def earned_value_impl(inp):
    pv, ev, ac, bac = (D(str(inp[k])) for k in ("planned_value", "earned_value", "actual_cost", "budget_at_completion"))
    if bac <= 0:
        raise DataError("budget_at_completion must be positive")
    if min(pv, ev, ac) < 0:
        raise DataError("planned value, earned value and actual cost must be non-negative")
    method = str(inp.get("eac_method", "cpi"))
    if method not in ("cpi", "budget_rate"):
        raise DataError("eac_method must be cpi or budget_rate")
    spi = ev / pv if pv > 0 else D(0)
    cpi = ev / ac if ac > 0 else D(0)
    eac = bac / cpi if method == "cpi" and cpi > 0 else ac + (bac - ev)
    out = {"planned_value": pv, "earned_value": ev, "actual_cost": ac, "budget_at_completion": bac,
           "schedule_variance": ev - pv, "cost_variance": ev - ac, "spi": spi, "cpi": cpi,
           "estimate_at_completion": eac,
           "estimate_to_complete": eac - ac, "variance_at_completion": bac - eac,
           "tcpi": (bac - ev) / (bac - ac) if bac != ac else D(0)}
    return out

def _evm_ref(inp):
    pv, ev, ac, bac = (float(D(str(inp[k]))) for k in ("planned_value", "earned_value", "actual_cost", "budget_at_completion"))
    cpi = ev / ac if ac else 0.0
    eac = bac / cpi if str(inp.get("eac_method", "cpi")) == "cpi" and cpi else ac + (bac - ev)
    return {"spi": ev / pv if pv else 0.0, "cpi": cpi, "estimate_at_completion": eac}

def earned_value_tests(inp, impl):
    base, ref = impl(inp), _evm_ref(inp)
    pv, ev, ac, bac = (D(str(inp[k])) for k in ("planned_value", "earned_value", "actual_cost", "budget_at_completion"))
    checks = [
        ("second_implementation_agrees", _close(base["spi"], ref["spi"], rel=1e-9)
         and _close(base["cpi"], ref["cpi"], rel=1e-9)
         and _close(base["estimate_at_completion"], ref["estimate_at_completion"], rel=1e-9), "float route agrees with the Decimal route"),
        ("schedule_variance_is_earned_minus_planned", _close(base["schedule_variance"], ev - pv), "SV = EV - PV"),
        ("cost_variance_is_earned_minus_actual", _close(base["cost_variance"], ev - ac), "CV = EV - AC"),
        ("spi_and_cpi_are_the_ratios", _close(base["spi"], ev / pv) and _close(base["cpi"], ev / ac), "SPI = EV/PV and CPI = EV/AC"),
        ("variance_at_completion_is_budget_minus_eac", _close(base["variance_at_completion"], bac - base["estimate_at_completion"]), "VAC = BAC - EAC"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def earned_value_profile(inp):
    try:
        bac = D(str(inp["budget_at_completion"]))
        if bac <= 0:
            return ["budget_at_completion must be positive"]
        for key in ("planned_value", "earned_value", "actual_cost"):
            if D(str(inp[key])) < 0:
                return [key + " must be non-negative"]
        if str(inp.get("eac_method", "cpi")) not in ("cpi", "budget_rate"):
            return ["eac_method must be cpi or budget_rate"]
        if D(str(inp["planned_value"])) == 0:
            return ["planned_value must be positive at the status date"]
        if D(str(inp["actual_cost"])) == 0:
            return ["actual_cost must be positive at the status date"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["earned-value inputs are malformed: planned_value, earned_value, actual_cost and budget_at_completion are required numbers"]

def _evm_typing(metric):
    if metric in ("spi", "cpi", "tcpi"):
        return ("ratio", 4)
    return ("currency", 2)

def earned_value_caveats(out, th):
    return ["The status date and the three cumulative figures are yours; the method does not derive them from a schedule.",
            "EAC is one declared convention: budget divided by CPI, or actual cost plus the remaining budget at the budgeted rate.",
            "Earned value measures progress against a plan; it cannot show whether the plan or the scope was right."]

def earned_value_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    return ("At the status date the schedule variance is " + tok("schedule_variance") + " and the cost variance is " +
            tok("cost_variance") + ", with SPI " + tok("spi") + " and CPI " + tok("cpi") +
            ". The estimate at completion is " + tok("estimate_at_completion") + " and the variance at completion is " +
            tok("variance_at_completion") + ".")


def oee_analysis_impl(inp):
    planned = D(str(inp["planned_production_time"]))
    downtime = D(str(inp["downtime"]))
    cycle = D(str(inp["ideal_cycle_time"]))
    total = D(str(inp["total_units"]))
    good = D(str(inp["good_units"]))
    if planned <= 0:
        raise DataError("planned_production_time must be positive")
    if downtime < 0 or downtime > planned:
        raise DataError("downtime must be between zero and the planned time")
    if cycle <= 0:
        raise DataError("ideal_cycle_time must be positive")
    if total < 0 or good < 0 or good > total:
        raise DataError("units must be non-negative and good units cannot exceed total units")
    run = planned - downtime
    availability = run / planned
    performance = (cycle * total / run) if run > 0 else D(0)
    quality = good / total if total > 0 else D(0)
    oee = availability * performance * quality
    return {"planned_production_time": planned, "downtime": downtime, "run_time": run,
            "ideal_cycle_time": cycle, "total_units": total, "good_units": good,
            "availability": availability, "performance": performance, "quality": quality, "oee": oee,
            "scrap_units": total - good,
            "theoretical_output": run / cycle if cycle > 0 else D(0)}

def _oee_ref(inp):
    planned = float(D(str(inp["planned_production_time"])))
    downtime = float(D(str(inp["downtime"])))
    cycle = float(D(str(inp["ideal_cycle_time"])))
    total = float(D(str(inp["total_units"])))
    good = float(D(str(inp["good_units"])))
    run = planned - downtime
    return {"availability": run / planned, "performance": cycle * total / run, "quality": good / total,
            "oee": (run / planned) * (cycle * total / run) * (good / total)}

def oee_analysis_tests(inp, impl):
    base, ref = impl(inp), _oee_ref(inp)
    checks = [
        ("second_implementation_agrees", all(_close(base[k], ref[k], rel=1e-9) for k in ref), "float route agrees with the Decimal route"),
        ("availability_is_run_time_over_planned_time", _close(base["availability"], base["run_time"] / base["planned_production_time"]), "availability uses the planned time less downtime"),
        ("performance_is_ideal_cycle_times_units_over_run_time", _close(base["performance"], base["ideal_cycle_time"] * base["total_units"] / base["run_time"]), "performance compares actual output with the ideal rate"),
        ("quality_is_good_units_over_total_units", _close(base["quality"], base["good_units"] / base["total_units"]), "quality is the good share of output"),
        ("oee_is_the_product_of_the_three", _close(base["oee"], base["availability"] * base["performance"] * base["quality"]), "OEE multiplies availability, performance and quality"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def oee_analysis_profile(inp):
    try:
        planned = D(str(inp["planned_production_time"]))
        downtime = D(str(inp["downtime"]))
        if planned <= 0:
            return ["planned_production_time must be positive"]
        if downtime < 0 or downtime > planned:
            return ["downtime must be between zero and the planned time"]
        if D(str(inp["ideal_cycle_time"])) <= 0:
            return ["ideal_cycle_time must be positive"]
        total = D(str(inp["total_units"])); good = D(str(inp["good_units"]))
        if total < 0 or good < 0 or good > total:
            return ["units must be non-negative and good units cannot exceed total units"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["OEE inputs are malformed: planned time, downtime, ideal cycle time and unit counts are required numbers"]

def _oee_typing(metric):
    if metric in ("availability", "performance", "quality", "oee"):
        return ("ratio", 4)
    if metric in ("total_units", "good_units", "scrap_units", "theoretical_output"):
        return ("units", 2)
    return ("periods", 2)

def oee_caveats(out, th):
    return ["OEE is arithmetic on the six figures you declare; the losses are not reclassified or assumed.",
            "Performance above one usually means the ideal cycle time or the unit count is wrong; the method reports it rather than capping it.",
            "OEE measures one machine or line, not a plant; six big losses and TEEP are not modelled."]

def oee_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    return ("Availability is " + tok("availability") + ", performance " + tok("performance") + " and quality " +
            tok("quality") + ", for an OEE of " + tok("oee") + ".")


def process_control_impl(inp):
    values = [D(str(x)) for x in inp["values"]]
    if len(values) < 5:
        raise DataError("at least five observations are required")
    n = len(values)
    mean = sum(values, D(0)) / n
    mrs = [abs(values[i] - values[i - 1]) for i in range(1, n)]
    mrbar = sum(mrs, D(0)) / len(mrs)
    if mrbar == 0:
        raise DataError("the series has no movement, so the control limits are undefined")
    sigma = mrbar / D("1.128")
    ucl = mean + 3 * sigma
    lcl = mean - 3 * sigma
    out = {"n": D(n), "mean": mean, "average_moving_range": mrbar, "sigma_estimate": sigma,
           "upper_control_limit": ucl, "lower_control_limit": lcl,
           "out_of_control": D(sum(1 for v in values if v > ucl or v < lcl))}
    run, longest, side = 1, 1, None
    for i in range(1, n):
        s = 1 if values[i] > mean else -1 if values[i] < mean else 0
        if s == side and s != 0:
            run += 1
        else:
            side, run = s, 1
        longest = max(longest, run)
    out["longest_run"] = D(longest)
    out["run_signal"] = D(1 if longest >= 8 else 0)
    lower = _optional_decimal(inp, "spec_lower")
    upper = _optional_decimal(inp, "spec_upper")
    if lower is not None and upper is not None:
        if upper <= lower:
            raise DataError("spec_upper must exceed spec_lower")
        cp = (upper - lower) / (6 * sigma)
        cpk = min((upper - mean) / (3 * sigma), (mean - lower) / (3 * sigma))
        out.update({"spec_lower": lower, "spec_upper": upper, "cp": cp, "cpk": cpk})
    return out

def _pc_ref(inp):
    vals = [float(D(str(x))) for x in inp["values"]]
    mean = sum(vals) / len(vals)
    mrbar = sum(abs(vals[i] - vals[i - 1]) for i in range(1, len(vals))) / (len(vals) - 1)
    sigma = mrbar / 1.128
    return {"mean": mean, "sigma_estimate": sigma, "upper_control_limit": mean + 3 * sigma}

def process_control_tests(inp, impl):
    base, ref = impl(inp), _pc_ref(inp)
    values = [D(str(x)) for x in inp["values"]]
    checks = [
        ("second_implementation_agrees", _close(base["mean"], ref["mean"], rel=1e-9)
         and _close(base["sigma_estimate"], ref["sigma_estimate"], rel=1e-9), "float route agrees with the Decimal route"),
        ("limits_are_the_mean_plus_or_minus_three_sigma",
         _close(base["upper_control_limit"], base["mean"] + 3 * base["sigma_estimate"])
         and _close(base["lower_control_limit"], base["mean"] - 3 * base["sigma_estimate"]), "the limits sit three estimated sigmas from the mean"),
        ("sigma_is_the_average_moving_range_over_one_point_one_two_eight",
         _close(base["sigma_estimate"], base["average_moving_range"] / D("1.128")), "the moving-range estimate uses the declared constant"),
        ("out_of_control_points_are_counted_against_the_limits",
         base["out_of_control"] == sum(1 for v in values if v > base["upper_control_limit"] or v < base["lower_control_limit"]), "the count is a fresh scan of the series"),
        ("cpk_is_the_distance_to_the_nearer_limit",
         "cpk" not in base or _close(base["cpk"], min((base["spec_upper"] - base["mean"]) / (3 * base["sigma_estimate"]),
                                                     (base["mean"] - base["spec_lower"]) / (3 * base["sigma_estimate"]))),
         "Cpk uses the nearer specification limit"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def process_control_profile(inp):
    try:
        vals = inp.get("values") or []
        if len(vals) < 5:
            return ["at least five observations are required"]
        nums = [D(str(x)) for x in vals]
        mrs = [abs(nums[i] - nums[i - 1]) for i in range(1, len(nums))]
        if sum(mrs, D(0)) == 0:
            return ["the series has no movement, so the control limits are undefined"]
        lower = _optional_decimal(inp, "spec_lower"); upper = _optional_decimal(inp, "spec_upper")
        if (lower is None) != (upper is None):
            return ["declare both spec_lower and spec_upper, or neither"]
        if lower is not None and upper <= lower:
            return ["spec_upper must exceed spec_lower"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["control-chart inputs are malformed: values is a list of numbers"]

def _pc_typing(metric):
    if metric in ("cp", "cpk"):
        return ("ratio", 4)
    if metric in ("n", "out_of_control", "longest_run", "run_signal"):
        return ("count", 0)
    if metric in ("spec_lower", "spec_upper"):
        return ("currency", 2)
    return ("ratio", 4)

def process_control_caveats(out, th):
    return ["The chart is an individuals chart with moving ranges (I-MR); subgroup charts, p-charts and EWMA are not computed.",
            "Control limits describe the variation of the series you supplied; they do not prove the process is capable or stable in future.",
            "Cp and Cpk use the estimated sigma and the specification limits you declare; no capability threshold is applied."]

def process_control_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    t = ("The mean is " + tok("mean") + " with an estimated sigma of " + tok("sigma_estimate") +
         ", giving control limits of " + tok("lower_control_limit") + " to " + tok("upper_control_limit") +
         ". " + tok("out_of_control") + " points fall outside the limits.")
    if "cpk" in out:
        t += " Against the declared specification, Cp is " + tok("cp") + " and Cpk is " + tok("cpk") + "."
    return t


def abc_costing_impl(inp):
    activities = inp["activities"]
    products = inp["products"]
    allocations = inp["allocations"]
    if not activities or not products or not allocations:
        raise DataError("activities, products and allocations are all required")
    pools, units = {}, {}
    for a in activities:
        name = str(a["name"]).strip()
        if not name or name in pools:
            raise DataError("activity names must be unique and non-empty")
        cost = D(str(a["pool_cost"]))
        if cost < 0:
            raise DataError("activity pool costs must be non-negative")
        pools[name] = cost
    for p in products:
        name = str(p["name"]).strip()
        if not name or name in units:
            raise DataError("product names must be unique and non-empty")
        q = D(str(p["units"]))
        if q <= 0:
            raise DataError("product units must be positive")
        units[name] = q
    drivers = {a: D(0) for a in pools}
    qty = {}
    for row in allocations:
        act = str(row["activity"]).strip(); prod = str(row["product"]).strip(); q = D(str(row["driver_quantity"]))
        if act not in pools:
            raise DataError("allocation cites unknown activity " + act)
        if prod not in units:
            raise DataError("allocation cites unknown product " + prod)
        if q < 0:
            raise DataError("driver quantities must be non-negative")
        drivers[act] += q
        qty[(act, prod)] = qty.get((act, prod), D(0)) + q
    rates = {}
    for act, cost in pools.items():
        if drivers[act] <= 0:
            raise DataError("activity " + act + " has no driver quantity to allocate against")
        rates[act] = cost / drivers[act]
    alloc = {p: D(0) for p in units}
    for (act, prod), q in qty.items():
        alloc[prod] += q * rates[act]
    out = {"total_pool_cost": sum(pools.values(), D(0)), "total_allocated": sum(alloc.values(), D(0))}
    for act in pools:
        out["rate_" + act] = rates[act]
        out["driver_" + act] = drivers[act]
    for prod in units:
        out["allocated_" + prod] = alloc[prod]
        out["unit_cost_" + prod] = alloc[prod] / units[prod]
    return out

def _abc_ref(inp):
    pools = {str(a["name"]).strip(): float(D(str(a["pool_cost"]))) for a in inp["activities"]}
    drivers = {a: 0.0 for a in pools}
    qty = {}
    for row in inp["allocations"]:
        act = str(row["activity"]).strip(); q = float(D(str(row["driver_quantity"])))
        drivers[act] += q
        qty[(act, str(row["product"]).strip())] = qty.get((act, str(row["product"]).strip()), 0.0) + q
    rates = {a: pools[a] / drivers[a] for a in pools}
    return {"total_allocated": sum(q * rates[a] for (a, _), q in qty.items())}

def abc_costing_tests(inp, impl):
    base, ref = impl(inp), _abc_ref(inp)
    products = [str(p["name"]).strip() for p in inp["products"]]
    checks = [
        ("second_implementation_agrees", _close(base["total_allocated"], ref["total_allocated"], rel=1e-9), "float route agrees with the Decimal route"),
        ("every_pool_is_allocated_in_full", _close(base["total_allocated"], base["total_pool_cost"]), "the allocated cost equals the pool cost"),
        ("rate_is_the_pool_cost_over_its_driver_total",
         all(_close(base["rate_" + a], D(str(next(x for x in inp["activities"] if str(x["name"]).strip() == a)["pool_cost"])) / base["driver_" + a])
             for a in (str(x["name"]).strip() for x in inp["activities"])), "each activity rate is its pool over its driver total"),
        ("unit_cost_is_the_allocation_over_units",
         all(_close(base["unit_cost_" + p], base["allocated_" + p] / D(str(next(x for x in inp["products"] if str(x["name"]).strip() == p)["units"])))
             for p in products), "each unit cost is the allocation over the declared units"),
        ("allocations_sum_to_the_total",
         _close(sum((base["allocated_" + p] for p in products), D(0)), base["total_allocated"]), "the per-product allocations add to the total"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def abc_costing_profile(inp):
    try:
        acts, prods, allocs = inp.get("activities"), inp.get("products"), inp.get("allocations")
        if not acts or not prods or not allocs:
            return ["activities, products and allocations are all required"]
        names = [str(a["name"]).strip() for a in acts]
        if len(set(names)) != len(names) or any(not n for n in names):
            return ["activity names must be unique and non-empty"]
        pnames = [str(p["name"]).strip() for p in prods]
        if len(set(pnames)) != len(pnames) or any(not n for n in pnames):
            return ["product names must be unique and non-empty"]
        for p in prods:
            if D(str(p["units"])) <= 0:
                return ["product units must be positive"]
        for a in acts:
            if D(str(a["pool_cost"])) < 0:
                return ["activity pool costs must be non-negative"]
        for row in allocs:
            if str(row["activity"]).strip() not in names:
                return ["allocation cites an unknown activity"]
            if str(row["product"]).strip() not in pnames:
                return ["allocation cites an unknown product"]
            if D(str(row["driver_quantity"])) < 0:
                return ["driver quantities must be non-negative"]
        for a in acts:
            total = sum((D(str(r["driver_quantity"])) for r in allocs if str(r["activity"]).strip() == str(a["name"]).strip()), D(0))
            if total <= 0 and D(str(a["pool_cost"])) > 0:
                return ["activity " + str(a["name"]).strip() + " has no driver quantity to allocate against"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["ABC inputs are malformed: activities, products and allocations are required records"]

def _abc_typing(metric):
    if metric.startswith("driver_"):
        return ("units", 2)
    if metric.startswith("rate_"):
        return ("currency", 4)
    if metric.startswith("unit_cost_"):
        return ("currency", 4)
    return ("currency", 2)

def abc_costing_caveats(out, th):
    return ["The activity pools, drivers and quantities are yours; the method does not choose the cost drivers.",
            "Every pool must be allocated in full; an activity with no driver quantity and a positive cost is refused rather than left unallocated.",
            "No idle capacity, unused capacity cost, or activity hierarchy (unit, batch, product, facility) is modelled."]

def abc_costing_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    t = ("The declared pools total " + tok("total_pool_cost") + " and are allocated in full to the products.")
    products = [k[10:] for k in out if k.startswith("allocated_")]
    if products:
        t += " Unit costs are reported for " + ", ".join(products) + "."
    return t


def sales_variances_impl(inp):
    products = inp["products"]
    if len(products) < 2:
        raise DataError("at least two products are required for a mix and yield variance")
    rows = []
    for p in products:
        name = str(p["name"]).strip()
        bu, bp, au, ap = (D(str(p[k])) for k in ("budget_units", "budget_price", "actual_units", "actual_price"))
        if not name or min(bu, bp, au, ap) < 0:
            raise DataError("each product needs a name and non-negative units and prices")
        rows.append({"name": name, "bu": bu, "bp": bp, "au": au, "ap": ap})
    total_bu = sum((r["bu"] for r in rows), D(0))
    total_au = sum((r["au"] for r in rows), D(0))
    if total_bu <= 0:
        raise DataError("budget units must sum to a positive total")
    out = {"budget_units": total_bu, "actual_units": total_au,
           "budget_revenue": sum((r["bu"] * r["bp"] for r in rows), D(0)),
           "actual_revenue": sum((r["au"] * r["ap"] for r in rows), D(0))}
    out["total_sales_variance"] = out["actual_revenue"] - out["budget_revenue"]
    mix_total = yield_total = price_total = D(0)
    for r in rows:
        share = r["bu"] / total_bu
        expected = share * total_au
        price = r["au"] * (r["ap"] - r["bp"])
        mix = r["bp"] * (r["au"] - expected)
        yield_v = r["bp"] * (expected - r["bu"])
        price_total += price; mix_total += mix; yield_total += yield_v
        out["price_variance_" + r["name"]] = price
        out["mix_variance_" + r["name"]] = mix
        out["yield_variance_" + r["name"]] = yield_v
    out.update({"price_variance": price_total, "mix_variance": mix_total,
                "yield_variance": yield_total,
                "volume_variance": mix_total + yield_total,
                "variance_check": price_total + mix_total + yield_total})
    return out

def _sales_ref(inp):
    rows = [(float(D(str(p["budget_units"]))), float(D(str(p["budget_price"]))),
             float(D(str(p["actual_units"]))), float(D(str(p["actual_price"])))) for p in inp["products"]]
    budget = sum(bu * bp for bu, bp, _, _ in rows)
    actual = sum(au * ap for _, _, au, ap in rows)
    return {"budget_revenue": budget, "actual_revenue": actual, "total_sales_variance": actual - budget}

def sales_variances_tests(inp, impl):
    base, ref = impl(inp), _sales_ref(inp)
    names = [str(p["name"]).strip() for p in inp["products"]]
    checks = [
        ("second_implementation_agrees", _close(base["budget_revenue"], ref["budget_revenue"], rel=1e-9)
         and _close(base["actual_revenue"], ref["actual_revenue"], rel=1e-9), "float route agrees with the Decimal route"),
        ("total_variance_is_actual_minus_budget_revenue", _close(base["total_sales_variance"], base["actual_revenue"] - base["budget_revenue"]), "the total is the revenue change"),
        ("price_mix_and_yield_add_to_the_total_variance",
         _close(base["variance_check"], base["total_sales_variance"]), "the three components reconstruct the total"),
        ("volume_variance_is_mix_plus_yield", _close(base["volume_variance"], base["mix_variance"] + base["yield_variance"]), "volume splits into mix and yield"),
        ("per_product_components_sum_to_the_totals",
         _close(sum((base["price_variance_" + n] for n in names), D(0)), base["price_variance"])
         and _close(sum((base["mix_variance_" + n] for n in names), D(0)), base["mix_variance"])
         and _close(sum((base["yield_variance_" + n] for n in names), D(0)), base["yield_variance"]), "the product rows add to each total"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def sales_variances_profile(inp):
    try:
        products = inp.get("products") or []
        if len(products) < 2:
            return ["at least two products are required for a mix and yield variance"]
        total = D(0); names = []
        for i, p in enumerate(products, 1):
            name = str(p.get("name") or "").strip()
            if not name or name in names:
                return ["product %d needs a unique name" % i]
            names.append(name)
            vals = [D(str(p[k])) for k in ("budget_units", "budget_price", "actual_units", "actual_price")]
            if min(vals) < 0:
                return ["product " + name + " needs non-negative units and prices"]
            total += vals[0]
        if total <= 0:
            return ["budget units must sum to a positive total"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["sales-variance inputs are malformed: each product needs budget and actual units and prices"]

def _sales_typing(metric):
    if "variance" in metric:
        return ("currency", 2)
    if metric.endswith("_units") or metric in ("budget_units", "actual_units"):
        return ("units", 2)
    return ("currency", 2)

def sales_variances_caveats(out, th):
    return ["Mix and yield are measured at the budgeted prices, with the budget mix held as the standard; a different convention changes the split.",
            "Price, mix and yield reconstruct the total revenue change; they do not explain why the mix or the price moved.",
            "Two or more products are required; a single product has a price and a volume variance only."]

def sales_variances_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    return ("Revenue moved by " + tok("total_sales_variance") + " against budget: a price variance of " +
            tok("price_variance") + ", a mix variance of " + tok("mix_variance") + " and a yield variance of " +
            tok("yield_variance") + ".")


def line_balancing_impl(inp):
    tasks = inp["tasks"]
    cycle = D(str(inp["cycle_time"]))
    rule = str(inp.get("rule", "longest_time"))
    if cycle <= 0:
        raise DataError("cycle_time must be positive")
    if rule not in ("longest_time", "ranked_positional"):
        raise DataError("rule must be longest_time or ranked_positional")
    if not tasks:
        raise DataError("at least one task is required")
    node, order = {}, []
    for t in tasks:
        name = str(t.get("id") or t.get("name") or "").strip()
        if not name or name in node:
            raise DataError("task ids must be unique and non-empty")
        dur = D(str(t["time"]))
        if dur <= 0:
            raise DataError("task " + name + " time must be positive")
        if dur > cycle:
            raise DataError("task " + name + " takes longer than the cycle time, so it cannot be balanced")
        preds = [p.strip() for p in str(t.get("predecessors") or "").split(",") if p.strip()]
        node[name] = {"time": dur, "preds": preds}
        order.append(name)
    for name, n in node.items():
        for p in n["preds"]:
            if p not in node:
                raise DataError("task " + name + " cites unknown predecessor " + p)
    succ = {name: [] for name in node}
    indeg = {name: len(n["preds"]) for name, n in node.items()}
    for name, n in node.items():
        for p in n["preds"]:
            succ[p].append(name)
    queue = [name for name in order if indeg[name] == 0]
    topo = []
    while queue:
        name = queue.pop(0)
        topo.append(name)
        for s in succ[name]:
            indeg[s] -= 1
            if indeg[s] == 0:
                queue.append(s)
    if len(topo) != len(node):
        raise DataError("the precedence graph contains a cycle")
    rpw = {}
    for name in reversed(topo):
        rpw[name] = node[name]["time"] + sum((rpw[s] for s in succ[name]), D(0))
    remaining = set(order)
    station_of, loads = {}, []
    while remaining:
        index = len(loads) + 1
        load = D(0)
        while True:
            ready = [t for t in order if t in remaining and all(p in station_of for p in node[t]["preds"])]
            fits = [t for t in ready if load + node[t]["time"] <= cycle]
            if not fits:
                break
            pick = max(fits, key=lambda t: (rpw[t] if rule == "ranked_positional" else node[t]["time"], -order.index(t)))
            station_of[pick] = index
            load += node[pick]["time"]
            remaining.discard(pick)
        loads.append(load)
    total = sum((node[t]["time"] for t in order), D(0))
    lower = (total / cycle).to_integral_value(rounding="ROUND_CEILING")
    out = {"total_time": total, "cycle_time": cycle, "task_count": D(len(order)),
           "stations": D(len(loads)), "lower_bound_stations": lower,
           "idle_time": D(len(loads)) * cycle - total,
           "efficiency": total / (D(len(loads)) * cycle)}
    for i, load in enumerate(loads, 1):
        out["load_%d" % i] = load
    for t in order:
        out["station_" + t] = D(station_of[t])
    return out

def _balance_ref(inp):
    cycle = float(D(str(inp["cycle_time"])))
    total = sum(float(D(str(t["time"]))) for t in inp["tasks"])
    import math as _m
    return {"stations_lower": _m.ceil(total / cycle), "total_time": total}

def line_balancing_tests(inp, impl):
    base, ref = impl(inp), _balance_ref(inp)
    tasks = inp["tasks"]
    names = [str(t.get("id") or t.get("name") or "").strip() for t in tasks]
    preds = {str(t.get("id") or t.get("name") or "").strip(): [p.strip() for p in str(t.get("predecessors") or "").split(",") if p.strip()] for t in tasks}
    loads = [base["load_%d" % i] for i in range(1, int(base["stations"]) + 1)]
    checks = [
        ("second_implementation_agrees", base["lower_bound_stations"] == D(ref["stations_lower"]), "the lower bound is the ceiling of total time over the cycle time"),
        ("every_task_is_assigned_once",
         sorted(int(base["station_" + t]) for t in names) == sorted(int(base["station_" + t]) for t in names)
         and all(1 <= int(base["station_" + t]) <= int(base["stations"]) for t in names), "each task sits in exactly one station"),
        ("no_station_exceeds_the_cycle_time", all(load <= base["cycle_time"] for load in loads), "every station fits inside the cycle time"),
        ("precedence_is_respected",
         all(int(base["station_" + p]) <= int(base["station_" + t]) for t in names for p in preds[t]), "a task never precedes one of its predecessors"),
        ("stations_are_at_least_the_lower_bound", base["stations"] >= base["lower_bound_stations"], "no packing can beat the theoretical minimum"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def line_balancing_profile(inp):
    try:
        cycle = D(str(inp["cycle_time"]))
        if cycle <= 0:
            return ["cycle_time must be positive"]
        tasks = inp.get("tasks") or []
        if not tasks:
            return ["at least one task is required"]
        if str(inp.get("rule", "longest_time")) not in ("longest_time", "ranked_positional"):
            return ["rule must be longest_time or ranked_positional"]
        names = []
        for i, t in enumerate(tasks, 1):
            name = str(t.get("id") or t.get("name") or "").strip()
            if not name or name in names:
                return ["task %d needs a unique id" % i]
            names.append(name)
            dur = D(str(t["time"]))
            if dur <= 0:
                return ["task " + name + " time must be positive"]
            if dur > cycle:
                return ["task " + name + " takes longer than the cycle time, so it cannot be balanced"]
        for t in tasks:
            for p in str(t.get("predecessors") or "").split(","):
                p = p.strip()
                if p and p not in names:
                    return ["task " + str(t.get("id") or t.get("name")).strip() + " cites unknown predecessor " + p]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["line-balancing inputs are malformed: tasks need a time and a cycle_time is required"]

def _balance_typing(metric):
    if metric in ("stations", "lower_bound_stations", "task_count") or metric.startswith("station_"):
        return ("count", 0)
    if metric.startswith("load_") or metric in ("total_time", "cycle_time", "idle_time"):
        return ("periods", 2)
    return ("ratio", 4)

def line_balancing_caveats(out, th):
    return ["The assignment uses the declared heuristic (longest task time or ranked positional weight); it is a good packing, not a proven optimum.",
            "Task times, precedence and the cycle time are yours; no learning curve, fatigue, parallel stations or mixed-model line is modelled.",
            "The lower bound is total work over the cycle time rounded up; idle time and efficiency are measured against the stations the heuristic used."]

def line_balancing_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    return ("The declared tasks total " + tok("total_time") + " against a cycle time of " + tok("cycle_time") +
            ", so at least " + tok("lower_bound_stations") + " stations are needed; the heuristic uses " +
            tok("stations") + ", with " + tok("idle_time") + " idle time and an efficiency of " + tok("efficiency") + ".")


def tax_declared_impl(inp):
    income = D(str(inp["taxable_income"]))
    rate = D(str(inp["income_tax_rate"]))
    if rate < 0 or rate > 1:
        raise DataError("income_tax_rate must be between zero and one")
    if income < 0:
        income_tax = D(0)
    else:
        income_tax = income * rate
    out = {"taxable_income": income, "income_tax_rate": rate, "income_tax": income_tax,
           "net_income_after_tax": income - income_tax}
    vat_out = _optional_decimal(inp, "vat_output_tax")
    vat_in = _optional_decimal(inp, "vat_input_tax")
    if vat_out is not None or vat_in is not None:
        if vat_out is None or vat_in is None:
            raise DataError("declare both vat_output_tax and vat_input_tax, or neither")
        if vat_out < 0 or vat_in < 0:
            raise DataError("VAT figures must be non-negative")
        out["vat_output_tax"] = vat_out
        out["vat_input_tax"] = vat_in
        out["vat_payable"] = vat_out - vat_in
    diff = _optional_decimal(inp, "temporary_difference")
    d_rate = _optional_decimal(inp, "deferred_tax_rate")
    if diff is not None or d_rate is not None:
        if diff is None or d_rate is None:
            raise DataError("declare both temporary_difference and deferred_tax_rate, or neither")
        if d_rate < 0 or d_rate > 1:
            raise DataError("deferred_tax_rate must be between zero and one")
        out["temporary_difference"] = diff
        out["deferred_tax_rate"] = d_rate
        out["deferred_tax"] = diff * d_rate
    out["total_tax_charge"] = out["income_tax"] + out.get("deferred_tax", D(0))
    return out

def _tax_declared_ref(inp):
    income = float(D(str(inp["taxable_income"])))
    rate = float(D(str(inp["income_tax_rate"])))
    tax = max(0.0, income) * rate
    diff = inp.get("temporary_difference")
    deferred = float(D(str(diff))) * float(D(str(inp.get("deferred_tax_rate", "0")))) if diff not in (None, "") else 0.0
    return {"income_tax": tax, "total_tax_charge": tax + deferred}

def tax_declared_tests(inp, impl):
    base, ref = impl(inp), _tax_declared_ref(inp)
    income = D(str(inp["taxable_income"]))
    rate = D(str(inp["income_tax_rate"]))
    checks = [
        ("second_implementation_agrees", _close(base["income_tax"], ref["income_tax"], rel=1e-9)
         and _close(base["total_tax_charge"], ref["total_tax_charge"], rel=1e-9), "float route agrees with the Decimal route"),
        ("income_tax_is_the_rate_on_positive_income", _close(base["income_tax"], max(D(0), income) * rate), "a loss carries no positive income tax in this declared calculation"),
        ("vat_payable_is_output_minus_input", "vat_payable" not in base or _close(base["vat_payable"], base["vat_output_tax"] - base["vat_input_tax"]), "VAT payable is output tax less input tax"),
        ("deferred_tax_is_the_rate_on_the_temporary_difference", "deferred_tax" not in base or _close(base["deferred_tax"], base["temporary_difference"] * base["deferred_tax_rate"]), "deferred tax applies the declared rate to the declared difference"),
        ("total_charge_is_income_tax_plus_deferred_tax", _close(base["total_tax_charge"], base["income_tax"] + base.get("deferred_tax", D(0))), "the total is the sum of the current and deferred charge"),
    ]
    return [(name, ok) for name, ok, _ in checks]

def tax_declared_profile(inp):
    try:
        rate = D(str(inp["income_tax_rate"]))
        if rate < 0 or rate > 1:
            return ["income_tax_rate must be between zero and one"]
        D(str(inp["taxable_income"]))
        vat_out = _optional_decimal(inp, "vat_output_tax"); vat_in = _optional_decimal(inp, "vat_input_tax")
        if (vat_out is None) != (vat_in is None):
            return ["declare both vat_output_tax and vat_input_tax, or neither"]
        if vat_out is not None and (vat_out < 0 or vat_in < 0):
            return ["VAT figures must be non-negative"]
        diff = _optional_decimal(inp, "temporary_difference"); d_rate = _optional_decimal(inp, "deferred_tax_rate")
        if (diff is None) != (d_rate is None):
            return ["declare both temporary_difference and deferred_tax_rate, or neither"]
        if d_rate is not None and (d_rate < 0 or d_rate > 1):
            return ["deferred_tax_rate must be between zero and one"]
        return []
    except (InvalidOperation, ValueError, TypeError, KeyError):
        return ["tax inputs are malformed: taxable_income and income_tax_rate are required numbers"]

def _tax_declared_typing(metric):
    if metric in ("income_tax_rate", "deferred_tax_rate"):
        return ("rate", 4)
    return ("currency", 2)

def tax_declared_caveats(out, th):
    return ["Every rate is declared by you. The method applies no jurisdiction's tax law, credits, exemptions, thresholds, NOLCO or filing rules.",
            "Taxable income is the declared figure, not an accounting profit recomputed from the statements; the deferred tax is the declared temporary difference times the declared rate.",
            "VAT payable is output tax less input tax, with no timing, classification or refund rules; a negative figure is a credit, not a refund claim."]

def tax_declared_template(out, P, th):
    tok = lambda k: "{{ref:%s:%s:%s}}" % (k, k, P)
    t = ("On taxable income of " + tok("taxable_income") + " at a declared rate of " + tok("income_tax_rate") +
         ", the income tax is " + tok("income_tax") + " and the after-tax income is " + tok("net_income_after_tax") + ".")
    if "vat_payable" in out:
        t += " VAT payable is " + tok("vat_payable") + "."
    if "deferred_tax" in out:
        t += " The deferred tax is " + tok("deferred_tax") + "."
    t += " The total tax charge is " + tok("total_tax_charge") + "."
    return t


